/* Views: today, words & dictionary, add/edit, word page, review, inbox, share */
(function () {
  'use strict';
  const A = window.App, G = A.G, esc = A.esc;
  A.acts = {}; A.forms = {}; A.changes = {}; A.inputs = {};

  // ---------------- TODAY ----------------
  A.routes.today = function () {
    const db = A.db, q = A.dueQueue();
    const n = q.due.length + q.fresh.length;
    const xp = A.todayXp(), goal = db.settings.goal, s = A.streak();
    const now = new Date();
    const date0 = now.toLocaleDateString(A.LANG.dateLocale, { weekday: 'long', day: 'numeric', month: 'long' }); const date = date0.charAt(0).toLocaleUpperCase() + date0.slice(1);
    const wod = A.wordsOfDay();
    const trouble = A.troubleWords();
    const irr = A.irregularOfDay();
    const ph = A.phraseOfDay();
    A.view().innerHTML = `
      <header class="hero">
        <div class="hero-text">
          <span class="hero-chips"><a class="lang-chip" href="#/settings" aria-label="Change language">${A.LANG.flag} ${esc(A.LANG.name)} ▾</a><a class="lang-chip gear" href="#/settings" aria-label="Settings">⚙️ Settings</a></span>
          <p class="hero-date">${esc(date)}</p>
          <h1>${esc(A.LANG.hello(now.getHours()))}</h1>
          <p class="hero-sub">${xp >= goal ? 'Daily goal reached. Ωραία!' : `${goal - xp} points to today's goal`}</p>
        </div>
        <a class="hero-ring" href="#/progress" aria-label="Today's progress">${A.ring(xp, goal, 92, 'Daily goal')}<span class="ring-num">${Math.min(xp, 999)}<small>/${goal}</small></span></a>
        <div class="meander" aria-hidden="true"></div>
      </header>
      <section class="review-cta ${n ? '' : 'done'}">
        ${db.words.length === 0 ? `
          <div><p class="cta-title">Start your word book</p><p class="cta-sub">Save a word of the day below, search the dictionary, or add something you just heard.</p></div>
          <a class="btn sun" href="#/words/dict">Open dictionary</a>
        ` : n ? `
          <div><p class="cta-title"><span class="big-num">${n}</span> to review</p><p class="cta-sub">${q.due.length} due · ${q.fresh.length} new</p></div>
          <a class="btn sun" href="#/review">Start</a>
        ` : `
          <div><p class="cta-title">Reviews done ✓</p><p class="cta-sub">Next due ${A.nextDueText()}. Keep going with a flash test.</p></div>
          <a class="btn sun" href="#/flash">Flash test</a>
        `}
      </section>
      <a class="streak-strip ${A.doneToday() ? 'lit' : ''}" href="#/badges">
        <span class="flame">${A.doneToday() ? '🔥' : s ? '🔥' : '🌑'}<b>${s}</b></span>
        <span class="week">${A.weekDots().map(d => `<span class="wd ${d.state}"><i>${d.state === 'done' ? '✓' : d.state === 'frozen' ? '🧊' : ''}</i><small>${d.label}</small></span>`).join('')}</span>
        <span class="lvl-pill">Lv ${A.levelInfo().level}</span>
      </a>
      <div class="mascot"><span class="m-face">${A.mascot.e}</span><p class="m-bubble">${esc(A.mascot.line())}</p></div>
      ${!A.remSettings().reminders && !A.global.remDismissed && A.db.words.length ? `<div class="rem-card"><span>🔔</span><p><strong>Get a daily reminder?</strong><br><small>Okto will nudge you so you don't lose your streak.</small></p><button class="btn sm primary" data-act="rem-on">Turn on</button><button class="icon-btn sm" data-act="rem-dismiss" aria-label="No thanks">✕</button></div>` : ''}


      ${A.levelCard ? A.levelCard() : ''}
      <a class="daily-card ${A.dailyDone() ? 'done' : ''}" href="#/daily"><span class="dc-ico">${A.dailyDone() ? '✅' : '📝'}</span><span class="dc-text"><strong>Today's test</strong><small>${A.dailyDone() ? `Done: ${A.dailyDone().score}/${A.dailyDone().total}. See you tomorrow!` : 'Words, listening, phrases and forms. +10 bonus XP'}</small></span><span class="dc-go">${A.dailyDone() ? '' : 'Start'}</span></a>
      <section>
        <div class="sec-head"><h2>Words of the day</h2><button class="linkish" data-act="speak-wod">Listen</button></div>
        <div class="wod-row">${wod.map(e => `
          <article class="wod g-tile-${e.gender || (e.pos === 'verb' ? 'v' : 'a')}">
            <button class="wod-main" data-act="open-entry" data-l="${esc(e.lemma)}">
              <span class="wod-art">${e.emoji ? `<span class="wod-emo">${e.emoji}</span>` : ''}${e.gender ? A.art(e.lemma, e.gender) : e.pos === 'verb' ? 'verb' : e.pos === 'adj' ? 'adj.' : ''}</span>
              <span class="wod-word" lang="${A.LANG.code}">${esc(e.lemma)}</span>
              <span class="wod-mean">${esc(e.meaning)}</span>
            </button>
            <button class="wod-add" data-act="add-entry" data-l="${esc(e.lemma)}" aria-label="Add ${esc(e.lemma)} to my words">+ Add</button>
          </article>`).join('')}</div>
      </section>

      <section>
        <h2>Remember today</h2>
        <ul class="remember">
          <li class="rm tip"><span class="rm-ico">💡</span><div><p class="rm-k">Grammar tip</p><p lang="${A.LANG.code}">${esc(A.tipOfDay())}</p></div></li>
          ${trouble.length ? `<li class="rm"><span class="rm-ico">🎯</span><div><p class="rm-k">Words you keep missing</p><p class="rm-words">${trouble.map(w => `<a href="#/word/${w.id}" lang="${A.LANG.code}">${A.headword(w)}</a> <span class="muted">${esc(w.meaning)}</span>`).join('<br>')}</p></div></li>` : ''}
          ${irr ? `<li class="rm"><span class="rm-ico">⚡</span><div><p class="rm-k">Irregular verb</p><p lang="${A.LANG.code}"><button class="linkish strong" data-act="open-entry" data-l="${esc(irr.lemma)}">${esc(irr.lemma)}</button> → ${esc(irr.line)} <span class="muted">${esc(irr.meaning)}</span></p></div></li>` : ''}
          ${ph ? `<li class="rm"><span class="rm-ico">💬</span><div><p class="rm-k">Say it today</p><p lang="${A.LANG.code}"><button class="linkish strong" data-act="speak" data-t="${esc(ph.gr)}">${esc(ph.gr)}</button><br><span class="muted">${esc(ph.en)}</span></p></div></li>` : ''}
        </ul>
      </section>

      <section class="capture">
        <h2>Quick capture</h2>
        <form data-form="capture" class="capture-form">
          <input name="text" placeholder="A word you just heard or read" autocomplete="off" autocapitalize="off" lang="${A.LANG.code}" required>
          <input name="ctx" placeholder="The sentence or where (optional)" autocomplete="off" lang="${A.LANG.code}">
          <button class="btn primary" type="submit">Save to inbox</button>
        </form>
        ${db.inbox.length ? `<a class="inbox-link" href="#/inbox"><strong>${db.inbox.length}</strong> in your inbox, waiting to be filed</a>` : ''}
      </section>

      <section class="quick-grid">
        <a href="#/flash" class="qtile t-sea"><span class="qt-ico">⚡</span><span>Flash test</span></a>
        <a href="#/read/${A.readings[A.dayIndex() % Math.max(1, A.readings.length)]?.id || ''}" class="qtile t-olive"><span class="qt-ico">📖</span><span>Today's read</span></a>
        <a href="#/grammar" class="qtile t-pom"><span class="qt-ico">🧩</span><span>Grammar</span></a>
        <a href="#/tutor" class="qtile t-sun"><span class="qt-ico">✨</span><span>Talk with ${A.AI}</span></a>
      </section>`;
  };
  A.acts['speak-wod'] = () => A.speak(A.wordsOfDay().map(e => A.entryHead(e)).join('. '));
  A.forms.capture = function (f, fd) {
    const text = (fd.get('text') || '').trim(); if (!text) return;
    A.db.inbox.push({ id: A.uid(), text, context: (fd.get('ctx') || '').trim(), source: 'Quick capture', created: Date.now() });
    A.save(); A.toast('Saved to inbox'); A.render();
  };

  // ---------------- WORDS & DICTIONARY ----------------
  let wordFilter = 'all', wordSearch = '';
  A.routes.words = function (arg) {
    const mode = arg === 'dict' ? 'dict' : 'mine';
    const filters = [['all', 'All']].concat(G.GENDERS.map(g => [g, G.G_TO_ART[g]])).concat([ ['verb', 'Verbs'], ['adj', 'Adjectives'], ['irr', 'Irregular'], ['other', 'Phrases']]);
    A.view().innerHTML = `
      <header class="top"><h1>Words</h1></header>
      <div class="seg big" role="tablist">
        <a href="#/words" class="${mode === 'mine' ? 'on' : ''}" role="tab">My words <span class="pill">${A.db.words.length}</span></a>
        <a href="#/words/dict" class="${mode === 'dict' ? 'on' : ''}" role="tab">Dictionary <span class="pill">${A.dict.length}</span></a>
      </div>
      <input class="search" type="search" placeholder="${mode === 'dict' ? `Search ${A.LANG.name} (any form) or English` : 'Search your words'}" value="${esc(wordSearch)}" data-input="search" lang="${A.LANG.code}" autocapitalize="off">
      ${mode === 'mine' ? `<div class="chips">${filters.map(([k, l]) => `<button class="chip ${wordFilter === k ? 'on' : ''} ${['m', 'f', 'n'].includes(k) ? 'g-' + k : ''}" data-act="filter" data-f="${k}">${l}</button>`).join('')}</div>` : `<p class="tiny">Type any form, like ${esc(A.LANG.formExample || '')}, and it finds the dictionary word.</p>`}
      <ul class="list words" id="wordlist"></ul>`;
    A.view().dataset.mode = mode;
    fillWords();
  };
  function fillWords() {
    const el = A.$('#wordlist'); if (!el) return;
    const mode = A.view().dataset.mode;
    if (mode === 'dict') {
      const res = wordSearch.trim() ? A.searchDict(wordSearch) : topicList();
      if (Array.isArray(res) && res.length && res[0].topicHeader !== undefined) { el.innerHTML = res.map(t => `<li class="topic-head">${esc(t.topicHeader)}</li>` + t.items.map(dictRow).join('')).join(''); return; }
      el.innerHTML = res.length ? res.map(dictRow).join('') : `<li class="empty">Not in the dictionary.<div class="row-btns"><button class="btn sm" data-act="ask-lookup" data-t="${esc(wordSearch)}">✨ Ask ${A.AI}</button><button class="btn sm" data-act="open-url" data-url="${esc(A.LANG.lookupUrl(wordSearch.trim()))}">Wiktionary</button><a class="btn sm" href="#/add/${encodeURIComponent(wordSearch.trim())}">Add it myself</a></div></li>`;
      return;
    }
    const s = G.strip(wordSearch.trim());
    const list = A.db.words.filter(w => {
      if (wordFilter === 'verb' && w.pos !== 'verb') return false;
      if (wordFilter === 'adj' && w.pos !== 'adj') return false;
      if (wordFilter === 'other' && w.pos !== 'other') return false;
      if (['m', 'f', 'n'].includes(wordFilter) && A.genderOf(w) !== wordFilter) return false;
      if (wordFilter === 'irr' && !A.isIrregular(w)) return false;
      if (s && !G.strip(w.lemma).includes(s) && !G.strip(w.meaning).includes(s) && !(w.tags || []).some(t => G.strip(t).includes(s))) return false;
      return true;
    }).sort((a, b) => b.created - a.created);
    el.innerHTML = list.length ? list.map(w => `
      <li><div class="word-row dict g-bar-${A.genderOf(w) || 'x'}"><a class="dr-main" href="#/word/${w.id}">
        <span class="wr-head">${A.headword(w)}${A.isIrregular(w) ? '<span class="irr-dot" title="Irregular"></span>' : ''}</span>
        <span class="wr-mean">${esc(w.meaning)}</span></a><button class="dr-say" data-act="speak" data-t="${esc(A.plainHead(w))}" aria-label="Listen">🔊</button></div></li>`).join('')
      : `<li class="empty">${A.db.words.length ? 'No words match.' : 'No words yet. Add from the dictionary, the words of the day, or tap +.'}</li>`;
  }
  function topicList() {
    const topics = [];
    A.dict.forEach(e => { let t = topics.find(x => x.topicHeader === e.topic); if (!t) topics.push(t = { topicHeader: e.topic, items: [] }); if (t.items.length < 6) t.items.push(e); });
    return topics;
  }
  function dictRow(e) {
    const mine = A.findByLemma(e.lemma);
    return `<li><div class="word-row dict g-bar-${e.gender || 'x'}">
      <button class="dr-main" data-act="open-entry" data-l="${esc(e.lemma)}"><span class="wr-head">${e.emoji ? `<span class="emo">${e.emoji}</span>` : ''}${e.gender ? `<span class="art g-${e.gender}">${A.artJoin(e.lemma, e.gender)}</span>` : ''}<span class="lemma">${esc(e.lemma)}</span> <span class="pos-tag">${posLabel(e)}</span></span><span class="wr-mean">${esc(e.meaning)}</span></button>
      <button class="dr-say" data-act="speak" data-t="${esc(A.entryHead(e))}" aria-label="Listen">🔊</button>
      ${mine ? `<a class="dr-add on" href="#/word/${mine.id}" aria-label="In your words">✓</a>` : `<button class="dr-add" data-act="add-entry" data-l="${esc(e.lemma)}" aria-label="Add">+</button>`}
    </div></li>`;
  }
  const posLabel = e => ({ noun: '', verb: 'verb', adj: 'adj', other: e.tag === 'adv' ? 'adv' : e.tag === 'conj' ? 'conj' : e.tag === 'prep' ? 'prep' : '' }[e.pos] || '');
  A.inputs.search = v => { wordSearch = v; fillWords(); };
  A.acts.filter = el => { wordFilter = el.dataset.f; A.render(); };
  const entryByLemma = l => A.dict.find(e => e.lemma === l);
  A.acts['open-entry'] = el => A.go('#/entry/' + encodeURIComponent(el.dataset.l));
  A.acts['add-entry'] = function (el) {
    const e = entryByLemma(el.dataset.l); if (!e) return;
    if (A.findByLemma(e.lemma)) return A.toast('Already in your words');
    const w = A.entryToWord(e);
    A.db.words.push(w); A.save(); A.resetIndex(); A.xp(1);
    A.toast('Added ' + A.plainHead(w));
    if (el.closest('.wod')) { el.textContent = '✓ Added'; el.disabled = true; }
    else if (el.classList.contains('dr-add')) { el.outerHTML = `<a class="dr-add on" href="#/word/${w.id}">✓</a>`; }
    else A.render();
  };

  // dictionary entry page (built-in word, not yet necessarily mine)
  A.routes.entry = function (lemma) {
    const e = entryByLemma(lemma);
    if (!e) return A.go('#/words/dict');
    const mine = A.findByLemma(e.lemma);
    if (mine) return A.go('#/word/' + mine.id);
    const w = A.entryToWord(e);
    const t = A.tableFor(w, A._allTenses);
    A.view().innerHTML = `
      <header class="top"><a class="back" href="#/words/dict">Dictionary</a></header>
      <section class="entry g-entry-${e.gender || 'x'}">
        <h1 class="entry-head" lang="${A.LANG.code}">${A.headword(w)}</h1>
        <p class="entry-meta">${esc(e.topic)} · ${['', 'core', 'intermediate', 'advanced'][e.level]}${posLabel(e) ? ' · ' + posLabel(e) : ''}</p>
        <p class="entry-mean">${esc(e.meaning)}</p>
        <div class="row-btns"><button class="btn primary" data-act="add-entry" data-l="${esc(e.lemma)}">+ Add to my words</button><button class="btn" data-act="speak" data-t="${esc(A.plainHead(w))}">🔊 Listen</button></div>
      </section>
      ${t ? `<section class="tables"><h2>${w.pos === 'verb' ? 'Conjugation' : 'Declension'}</h2>${A.renderTable(w, t, true)}${moreTenses(t)}</section>` : ''}
      ${sameTopic(e)}`;
  };
  function sameTopic(e) {
    const rel = A.dict.filter(x => x.topic === e.topic && x !== e).slice(0, 8);
    return rel.length ? `<section><h2>More from ${esc(e.topic)}</h2><div class="chips wrap">${rel.map(x => `<button class="chip" data-act="open-entry" data-l="${esc(x.lemma)}" lang="${A.LANG.code}">${x.emoji || ''} ${esc(A.entryHead(x))}</button>`).join('')}</div></section>` : '';
  }

  // lookup sheet: used from reading texts, tutor chat, phrases
  A.acts.lookup = function (el) {
    const tok = el.dataset.t;
    const hits = A.lookupForm(tok);
    const seen = new Set();
    const items = hits.filter(h => { const k = h.kind === 'dict' ? 'd' + h.e.lemma : 'm' + h.id; if (seen.has(k)) return false; seen.add(k); return true; }).slice(0, 4);
    const body = items.length ? items.map(h => {
      if (h.kind === 'mine') { const w = A.findWord(h.id); return w ? `<div class="lk"><p class="lk-word" lang="${A.LANG.code}">${A.headword(w)}</p><p>${esc(w.meaning)}</p><div class="row-btns"><a class="btn sm" href="#/word/${w.id}" data-act="sheet-close-go">Open</a><button class="btn sm" data-act="speak" data-t="${esc(A.plainHead(w))}">🔊</button><span class="tiny">In your words</span></div></div>` : ''; }
      const e = h.e;
      return `<div class="lk"><p class="lk-word" lang="${A.LANG.code}">${e.emoji ? `<span class="emo">${e.emoji}</span>` : ''}${e.gender ? `<span class="art g-${e.gender}">${A.artJoin(e.lemma, e.gender)}</span>` : ''}<span class="lemma">${esc(e.lemma)}</span></p><p>${esc(e.meaning)}</p>
        <div class="row-btns"><button class="btn sm primary" data-act="add-entry-sheet" data-l="${esc(e.lemma)}" data-ctx="${esc(el.dataset.ctx || '')}">+ Add</button><button class="btn sm" data-act="entry-sheet" data-l="${esc(e.lemma)}">Forms</button><button class="btn sm" data-act="speak" data-t="${esc(e.lemma)}">🔊</button></div></div>`;
    }).join('') : `<p class="muted">Not in the dictionary.</p><div class="row-btns"><button class="btn sm" data-act="ask-lookup" data-t="${esc(tok)}" data-ctx="${esc(el.dataset.ctx || '')}">✨ Ask ${A.AI}</button><a class="btn sm" href="#/add/${encodeURIComponent(tok)}" data-act="sheet-close-go">+ Add it myself</a><button class="btn sm" data-act="inbox-token" data-t="${esc(tok)}">Save to inbox</button><button class="btn sm" data-act="open-url" data-url="${esc(A.LANG.lookupUrl(tok))}">Wiktionary</button></div>`;
    const ctxBtn = items.length && el.dataset.ctx && A.aiReady() ? `<button class="btn sm ghost wide" data-act="ask-lookup" data-t="${esc(tok)}" data-ctx="${esc(el.dataset.ctx)}">✨ What does it mean in this sentence?</button>` : '';
    A.sheet(`<h2 lang="${A.LANG.code}">${esc(tok)}</h2>${el.dataset.ctx ? `<p class="lk-ctx" lang="${A.LANG.code}">${esc(el.dataset.ctx)}</p>` : ''}${body}${ctxBtn}`);
    if (!items.length && A.aiReady()) A.acts['ask-lookup'](el);
  };
  A.acts['add-entry-sheet'] = function (el) {
    const e = entryByLemma(el.dataset.l); if (!e) return;
    if (A.findByLemma(e.lemma)) { A.closeSheet(); return A.toast('Already in your words'); }
    const w = A.entryToWord(e, el.dataset.ctx ? { examples: [{ text: el.dataset.ctx, source: 'Reading' }] } : {});
    A.db.words.push(w); A.save(); A.resetIndex(); A.xp(1); A.closeSheet(); A.toast('Added ' + A.plainHead(w));
  };
  A.acts['entry-sheet'] = el => { A.closeSheet(); A.go('#/entry/' + encodeURIComponent(el.dataset.l)); };
  A.acts['sheet-close-go'] = () => A.closeSheet();
  A.acts['inbox-token'] = el => { A.db.inbox.push({ id: A.uid(), text: el.dataset.t, context: '', source: 'Lookup', created: Date.now() }); A.save(); A.closeSheet(); A.toast('Saved to inbox'); };
  A.acts['ask-lookup'] = async function (el) {
    const tok = (el.dataset.t || '').trim(); if (!tok) return;
