    const ctx = el.dataset.ctx || '';
    A.sheet(`<h2 lang="${A.LANG.code}">${esc(tok)}</h2><p class="muted thinking">Asking ${A.AI}…</p>`);
    try {
      const msg = ctx ? `${tok}\n\nIt appears in this sentence: "${ctx}". Give the meaning it has here. Leave "example" as "" and put the sentence's English translation in "notes".` : tok;
      const once = () => A.ask({ system: window.AI.prompts.lookup, messages: [{ role: 'user', content: msg }], maxTokens: 2000 }).then(window.AI.parseJSON);
      let d; try { d = await once(); } catch (e1) { if (/NO_KEY|API key|credit|connection/i.test(e1.message)) throw e1; d = await once(); } // one quiet retry
      if (!d || !d.lemma) throw new Error(A.AI + ' didn\'t recognise that word. Try again.');
      if (ctx) { d.example = ctx; d._src = 'Reading'; }
      A._aiWord = d;
      const g = G.ART_TO_G[d.article] || '';
      A.sheet(`<h2 lang="${A.LANG.code}">${g ? `<span class="art g-${g}">${esc(d.article)}</span> ` : ''}${esc(d.lemma)}</h2><p>${esc(d.meaning)}</p>${d.example ? `<p class="ex" lang="${A.LANG.code}">${esc(d.example)}</p>` : ''}${d.notes ? `<p class="tiny">${esc(d.notes)}</p>` : ''}
        <div class="row-btns"><button class="btn primary" data-act="add-ai-word">+ Add to my words</button><button class="btn" data-act="speak" data-t="${esc(d.lemma)}">🔊</button></div>`);
    } catch (e) { A.sheet(`<h2>Couldn't look that up</h2><p class="muted">${esc(e.message === 'NO_KEY' ? 'Add your API key in Settings.' : e.message)}</p>`); }
  };
  A.addAiWord = function (d, source) {
    if (A.findByLemma(d.lemma)) { A.toast('Already in your words'); return null; }
    const head = (d.article ? d.article + ' ' : '') + d.lemma;
    const a = G.analyse(head, { pos: d.pos });
    const ov = {}; if (d.aorist) ov.aorist = d.aorist; if (d.future) ov.future = d.future;
    const w = A.newWord({ lemma: d.lemma, pos: a.pos, gender: a.gender || '', article: d.article || '', paradigm: a.paradigm || null, group: a.group || null,
      meaning: d.meaning || '', note: d.notes || '', ov, irregular: !!d.aorist, examples: d.example ? [{ text: d.example, source: source || A.AI }] : [], source: source || A.AI });
    A.db.words.push(w); A.save(); A.resetIndex(); A.xp(1);
    A.toast('Added ' + A.plainHead(w));
    return w;
  };
  A.acts['add-ai-word'] = () => { if (A._aiWord) A.addAiWord(A._aiWord, A._aiWord._src); A.closeSheet(); };

  // ---------------- INBOX ----------------
  A.routes.inbox = function () {
    A.view().innerHTML = `
      <header class="top"><a class="back" href="#/today">Today</a><h1>Inbox</h1>
      <p class="muted">Words you captured on the go. File each one to give it grammar and start reviewing it.</p></header>
      ${A.db.inbox.length ? `<ul class="list">${A.db.inbox.slice().reverse().map(it => {
        const hit = A.lookupForm(it.text).find(h => h.kind === 'dict');
        return `<li class="inbox-item">
          <div><p class="lemma-sm" lang="${A.LANG.code}">${esc(it.text)}</p>${hit ? `<p class="tiny">Dictionary: ${esc(A.entryHead(hit.e))}, ${esc(hit.e.meaning)}</p>` : ''}${it.context ? `<p class="ctx" lang="${A.LANG.code}">${esc(it.context)}</p>` : ''}<p class="tiny">${esc(it.source || '')} · ${new Date(it.created).toLocaleDateString('en-GB')}</p></div>
          <div class="item-btns"><button class="btn sm primary" data-act="file" data-id="${it.id}">File</button><button class="btn sm ghost" data-act="inbox-del" data-id="${it.id}" aria-label="Delete">✕</button></div>
        </li>`; }).join('')}</ul>` : `<p class="empty">Nothing waiting. Capture words from Today, or select text in Instagram or Chrome and choose Λέξεις.</p>`}`;
  };
  A.acts.file = function (el) {
    const it = A.db.inbox.find(i => i.id === el.dataset.id); if (!it) return;
    const hit = A.lookupForm(it.text).find(h => h.kind === 'dict');
    if (hit && !A.findByLemma(hit.e.lemma)) {
      const w = A.entryToWord(hit.e, { examples: it.context ? [{ text: it.context, source: it.source }] : [], source: it.source });
      A.db.words.push(w); A.db.inbox = A.db.inbox.filter(x => x.id !== it.id); A.save(); A.resetIndex(); A.xp(1);
      A.toast('Filed as ' + A.plainHead(w)); return A.go('#/word/' + w.id);
    }
    A.go('#/add/inbox:' + it.id);
  };
  A.acts['inbox-del'] = el => { A.db.inbox = A.db.inbox.filter(x => x.id !== el.dataset.id); A.save(); A.render(); };

  // ---------------- SHARE ----------------
  A.shared = null;
  A.routes.share = function () {
    const sh = A.shared;
    if (!sh) return A.go('#/today');
    const url = (sh.text.match(/https?:\/\/\S+/) || [])[0] || '';
    const src = /instagram/i.test(url) ? 'Instagram' : /youtu/i.test(url) ? 'YouTube' : /tiktok/i.test(url) ? 'TikTok' : url ? 'Web' : 'Shared';
    const body = sh.text.replace(/https?:\/\/\S+/g, '').trim();
    const tokens = Array.from(new Set((body.match(A.LANG.wordRe) || []).filter(t => t.length > 1)));
