    A.view().innerHTML = `
      <header class="top"><h1>Add from ${esc(src)}</h1></header>
      ${body ? `<blockquote class="shared-text" lang="${A.LANG.code}">${esc(body.slice(0, 600))}</blockquote>` : ''}
      ${tokens.length ? `<p class="muted">Tap the words you want to keep.</p>
        <div class="tokens">${tokens.slice(0, 80).map(t => `<button class="token" data-act="tok" data-t="${esc(t)}">${esc(t)}</button>`).join('')}</div>
        <div class="row-btns sticky-btns"><button class="btn primary" data-act="share-inbox" disabled>Save to inbox</button><button class="btn" data-act="share-now" disabled>Add one now</button></div>`
      : `<p class="muted">${url ? 'Instagram shares only the link, not the words.' : ''} Type the word you heard. The link is kept as its source.</p>
        <form data-form="share-type" class="capture-form"><input name="text" placeholder="The word" lang="${A.LANG.code}" required autocomplete="off"><input name="ctx" placeholder="The sentence, if you remember it" lang="${A.LANG.code}" autocomplete="off"><button class="btn primary" type="submit">Save to inbox</button></form>`}
      <button class="btn ghost" data-act="share-cancel">Cancel</button>`;
  };
  const sentenceAround = (body, word) => ((body.split(/(?<=[.;!?·\n])\s+/).find(p => p.includes(word)) || body).trim().slice(0, 300));
  A.acts.tok = function (el) {
    el.classList.toggle('on');
    const n = A.$$('.token.on').length;
    A.$('[data-act="share-inbox"]').disabled = !n; A.$('[data-act="share-now"]').disabled = n !== 1;
  };
  A.acts['share-inbox'] = function () {
    const sh = A.shared, sel = A.$$('.token.on').map(b => b.dataset.t);
    sel.forEach(t => A.db.inbox.push({ id: A.uid(), text: G.lower(t), context: sentenceAround(sh.body, t), source: sh.src + (sh.url ? ' ' + sh.url : ''), created: Date.now() }));
    A.save(); A.shared = null; A.toast(`${sel.length} saved to inbox`); A.go('#/inbox');
  };
  A.acts['share-now'] = function () { const t = A.$('.token.on').dataset.t; A.shared.ctx = sentenceAround(A.shared.body, t); A.go('#/add/' + encodeURIComponent(G.lower(t))); };
  A.acts['share-cancel'] = () => { A.shared = null; A.go('#/today'); };
  A.forms['share-type'] = function (f, fd) {
    const sh = A.shared || { src: 'Shared' };
    A.db.inbox.push({ id: A.uid(), text: (fd.get('text') || '').trim(), context: (fd.get('ctx') || '').trim(), source: sh.src + (sh.url ? ' ' + sh.url : ''), created: Date.now() });
    A.save(); A.shared = null; A.toast('Saved to inbox'); A.go('#/inbox');
  };
  window.__lexeisShare = function (text, sid) {
    if (!text) return 1;
    if (sid && A.db.lastShare === sid) return 1;
    A.db.lastShare = sid || Date.now(); A.save();
    A.shared = { text: String(text) };
    const body = A.shared.text.replace(/https?:\/\/\S+/g, '').trim();
    const tokens = body.match(A.LANG.wordRe) || [];
    if (tokens.length === 1 && body.split(/\s+/).length <= 3) {
      A.shared.src = 'Shared'; A.shared.body = body;
      const hit = A.lookupForm(tokens[0]).find(h => h.kind === 'dict');
      if (hit) A.go('#/entry/' + encodeURIComponent(hit.e.lemma)); else A.go('#/add/' + encodeURIComponent(G.lower(tokens[0])));
    } else A.go('#/share');
    return 1;
  };

  // ---------------- ADD / EDIT ----------------
  let draft = null;
  A.routes.add = function (prefill) { renderAdd(prefill); };
  A.routes.edit = function (id) { renderAdd('', id); };
  function renderAdd(prefill, editId) {
    const editing = editId ? A.findWord(editId) : null;
    if (editing) draft = JSON.parse(JSON.stringify(editing));
    else {
      const inboxItem = prefill && prefill.startsWith('inbox:') ? A.db.inbox.find(i => i.id === prefill.slice(6)) : null;
      const text = inboxItem ? inboxItem.text : prefill;
      draft = A.newWord({ _input: text || '', _inbox: inboxItem ? inboxItem.id : null,
        examples: inboxItem && inboxItem.context ? [{ text: inboxItem.context, source: inboxItem.source || '' }] : [], source: inboxItem ? inboxItem.source || '' : '' });
      if (A.shared && A.shared.ctx && !inboxItem) { draft.examples = [{ text: A.shared.ctx, source: A.shared.src }]; draft.source = A.shared.src; }
      if (text) applyAnalysis(text);
    }
    const input = editing ? A.plainHead(editing) : draft._input;
    const ex = draft.examples[0] || {};
    A.view().innerHTML = `
      <header class="top">${editing ? `<a class="back" href="#/word/${editing.id}">Back</a>` : ''}<h1>${editing ? 'Edit word' : 'Add a word'}</h1></header>
      <form data-form="word" class="word-form" autocomplete="off">
        <label class="field"><span>${A.LANG.name}${A.LANG.code === 'el' ? ' (or type English)' : ''}</span><input name="greek" value="${esc(input)}" placeholder="${esc(A.LANG.addPlaceholder)}${A.LANG.code === 'el' ? ', or English' : ''}" lang="${A.LANG.code}" autocapitalize="off" spellcheck="false" required data-input="greek"></label>
        <div id="dictHint"></div>
        <div id="analysis"></div>
        <label class="field"><span>Meaning</span><input name="meaning" value="${esc(draft.meaning)}" placeholder="In English" autocapitalize="off" oninput="this.dataset.auto=''"></label>
        <label class="field"><span>Example sentence</span><textarea name="example" rows="2" lang="${A.LANG.code}" placeholder="Where you saw or heard it">${esc(ex.text || '')}</textarea></label>
        <label class="field"><span>Source</span><input name="source" value="${esc(draft.source || ex.source || '')}" placeholder="Instagram, a book, a friend…" list="sources"></label>
        <datalist id="sources"><option value="Instagram"><option value="Reading"><option value="TV / film"><option value="Podcast"><option value="Conversation"></datalist>
        <label class="field"><span>Note</span><input name="note" value="${esc(draft.note)}" placeholder="Anything to remember about it"></label>
        <label class="field"><span>Tags</span><input name="tags" value="${esc((draft.tags || []).join(', '))}" placeholder="food, work, slang"></label>
        <div id="dup"></div>
        <button class="btn primary wide" type="submit">${editing ? 'Save changes' : 'Save word'}</button>
      </form>`;
    renderAnalysis();
  }
  function applyAnalysis(text, keep) {
    if (A.isEnglishInput(text || '')) { Object.assign(draft, { lemma: '', article: '', gender: '', paradigm: null, group: null }); return; }
    const a = G.analyse(text, keep || {});
    Object.assign(draft, { lemma: a.lemma, article: a.article, pos: a.pos, gender: a.gender || '', paradigm: a.paradigm || null, group: a.group || null, conf: a.conf });
  }
  function renderAnalysis() {
    const el = A.$('#analysis'); if (!el) return;
    renderSuggest();
    if (!draft.lemma) { el.innerHTML = ''; return; }
    const pos = [['noun', 'Noun'], ['verb', 'Verb'], ['adj', 'Adjective'], ['other', 'Other']];
    let html = `<div class="analysis"><div class="seg" role="radiogroup" aria-label="Part of speech">${pos.map(([k, l]) => `<button type="button" class="${draft.pos === k ? 'on' : ''}" data-act="pos" data-v="${k}">${l}</button>`).join('')}</div>`;
    if (draft.pos === 'noun') {
      html += `<div class="seg gender-seg" role="radiogroup" aria-label="Gender">${G.GENDERS.map(g => `<button type="button" class="g-${g} ${draft.gender === g ? 'on' : ''}" data-act="gender" data-v="${g}">${G.G_TO_ART[g]}</button>`).join('')}</div>`;
      if (!draft.gender) html += `<p class="hint">Pick the article. -ος words can be any gender.</p>`;
      else if (draft.conf === 'mid' && !draft.article) html += `<p class="hint">Guessed from the ending. -ος words are usually masculine, but check: η οδός, το λάθος.</p>`;
      const opts = Object.entries(G.PARADIGMS).filter(([, p]) => !draft.gender || p.g === draft.gender);
      html += `<label class="field inline"><span>Pattern</span><select data-change="paradigm"><option value="">Irregular / fill in myself</option>${opts.map(([k, p]) => `<option value="${k}" ${draft.paradigm === k ? 'selected' : ''}>${esc(p.label)}</option>`).join('')}</select></label>`;
      if (draft.paradigm) { const d = G.declineWith(draft.lemma, draft.paradigm); const g = draft.gender; html += `<p class="preview">${G.ARTICLES[g].sg[1]} <b>${esc(d['sg.gen'])}</b> · ${G.ARTICLES[g].pl[0]} <b>${esc(d['pl.nom'])}</b> · ${G.ARTICLES[g].pl[1]} <b>${esc(d['pl.gen'])}</b></p>`; }
    } else if (draft.pos === 'verb') {
      html += `<label class="field inline"><span>Group</span><select data-change="group">${Object.entries(G.GROUPS).map(([k, l]) => `<option value="${k}" ${draft.group === k ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>`;
      const c = G.conjugate(draft.lemma, draft.group, draft.ov);
      if (c && c.tenses.aorist) {
        html += `<p class="preview">${esc(c.tenses.aorist[0])} · ${esc((c.tenses.future || [''])[0])} · ${esc(c.tenses.imperfect[0])}</p>`;
        if (c.conf.aorist === 'low' || c.conf.aorist === 'mid') html += `<p class="hint">The aorist is a guess. If it's irregular, fix it on the word page after saving.</p>`;
      }
    } else if (draft.pos === 'adj') {
      const a = G.declineAdj(draft.lemma);
      html += a ? `<p class="preview"><b class="g-m">${esc(a.m['sg.nom'])}</b> · <b class="g-f">${esc(a.f['sg.nom'])}</b> · <b class="g-n">${esc(a.n['sg.nom'])}</b></p>` : `<p class="hint">Only -ος adjectives are generated. You can fill in forms yourself.</p>`;
    }
    el.innerHTML = html + '</div>';
    const dup = A.$('#dup');
    if (dup) { const d = A.db.words.find(w => w.id !== draft.id && G.strip(w.lemma) === G.strip(draft.lemma)); dup.innerHTML = d ? `<p class="hint warn">Already in your words: <a href="#/word/${d.id}">${esc(A.plainHead(d))}</a></p>` : ''; }
  }
  // suggestions under the word box: dictionary match + meaning, "did you mean", English → Greek, Ask Claude
  function renderSuggest() {
    const box = A.$('#dictHint'), inp = A.$('[data-input="greek"]'); if (!box || !inp) return;
    const q = inp.value.trim(), L = A.LANG.code;
    if (draft.id && A.findWord(draft.id)) { box.innerHTML = ''; return; } // editing an existing word
    if (q.length < 2) { box.innerHTML = ''; return; }
    const row = (e, label) => { const mine = A.findByLemma(e.lemma); return `<div class="sug-row"><button type="button" class="sug-main" data-act="sug-use" data-l="${esc(e.lemma)}"><b lang="${L}">${e.emoji ? e.emoji + ' ' : ''}${esc(A.entryHead(e))}</b><small>${esc(e.meaning)}</small></button>${mine ? `<a class="btn sm" href="#/word/${mine.id}">Yours</a>` : `<button type="button" class="btn sm primary" data-act="use-dict" data-l="${esc(e.lemma)}">${label || '+ Add'}</button>`}</div>`; };
    const ai = A.aiReady() ? `<button type="button" class="btn sm ghost" data-act="sug-ai">✨ Ask ${A.AI}${A.isEnglishInput(q) ? ' for the ' + A.LANG.name : ''}</button>` : '';
    let html = '';
    const mf = A.$('input[name="meaning"]'); if (mf && mf.dataset.auto === '1') { mf.value = ''; mf.dataset.auto = ''; } // drop a meaning we filled for an earlier spelling
    if (A.isEnglishInput(q)) {
      const hits = A.englishSearch(q);
      html = hits.length ? `<p class="sug-h">${esc(A.LANG.name)} for “${esc(q)}”</p>${hits.map(e => row(e)).join('')}${ai}` : `<p class="sug-h">No ${esc(A.LANG.name)} word for “${esc(q)}” in the dictionary.</p>${ai || '<p class="tiny">Add an AI key in Settings to translate any word.</p>'}`;
    } else {
      const exact = draft.lemma ? A.lookupForm(draft.lemma).filter(h => h.kind === 'dict').map(h => h.e) : [];
      const uniq = Array.from(new Set(exact)).slice(0, 2);
      const close = A.closeMatches(q, uniq.map(e => e.lemma)).slice(0, uniq.length ? 3 : 5);
      if (uniq.length) {
        html += `<p class="sug-h ok">✓ In the dictionary</p>${uniq.map(e => row(e)).join('')}`;
        const m = A.$('input[name="meaning"]');
        if (m && (!m.value.trim() || m.dataset.auto === '1')) { m.value = uniq[0].meaning; m.dataset.auto = '1'; }
      }
      if (close.length) html += `<p class="sug-h">${uniq.length ? 'Also close' : 'Did you mean…'}</p>${close.map(e => row(e)).join('')}`;
      if (L !== 'el' && !uniq.length) { const en = A.englishSearch(q).filter(e => !close.includes(e)).slice(0, 4); if (en.length) html += `<p class="sug-h">${esc(A.LANG.name)} for “${esc(q)}” (English)</p>${en.map(e => row(e)).join('')}`; }
      if (!uniq.length && draft._aiFor === q) html = `<p class="sug-h ok">${draft._aiNote}</p>`;
      else if (!uniq.length) html += close.length ? ai : `<p class="sug-h">Not in the dictionary.</p>${ai || '<p class="tiny">Fill in the meaning yourself, or add an AI key in Settings to check spelling and meaning.</p>'}`;
    }
    box.innerHTML = `<div class="sug">${html}</div>`;
  }
  A.acts['sug-use'] = function (el) {
    const e = entryByLemma(el.dataset.l); if (!e) return;
    const inp = A.$('[data-input="greek"]'); inp.value = A.entryHead(e);
    const m = A.$('input[name="meaning"]'); if (m) { m.value = e.meaning; m.dataset.auto = '1'; }
    draft._fromEntry = e.lemma; draft._posLocked = false; draft._genderLocked = false;
    A.inputs.greek(inp.value);
  };
  A.acts['sug-ai'] = async function () {
    const inp = A.$('[data-input="greek"]'), q = inp.value.trim(), box = A.$('#dictHint'); if (!q) return;
    const en = A.isEnglishInput(q);
    box.innerHTML = `<div class="sug"><p class="muted thinking">Asking ${A.AI}…</p></div>`;
    try {
      const msg = en ? `English: "${q}". Give the most common ${A.LANG.name} word for this, in the JSON format.` : q;
      const once = () => A.ask({ system: window.AI.prompts.lookup, messages: [{ role: 'user', content: msg }], maxTokens: 2000 }).then(window.AI.parseJSON);
      let d; try { d = await once(); } catch (e1) { if (/NO_KEY|API key|credit|connection/i.test(e1.message)) throw e1; d = await once(); }
      if (!d || !d.lemma) throw new Error(A.AI + ' didn\'t recognise that. Check the spelling.');
      inp.value = (d.article ? d.article + ' ' : '') + d.lemma;
