    for (let i = 1; i < items.length; i++) if (items[i].w.id === items[i - 1].w.id) { const j = items.findIndex((x, k) => k > i && x.w.id !== items[i].w.id); if (j > 0) [items[i], items[j]] = [items[j], items[i]]; }
