      front += `<form data-form="typed" class="typed"><input name="a" lang="${A.LANG.code}" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the form">${A.canListen() ? '<button type="button" class="icon-btn mic" data-act="mic-fill" aria-label="Say it">🎙️</button>' : ''}<button class="btn primary" type="submit">Check</button></form>`;
      back = `<p class="verdict"></p><p class="card-word sm" lang="${A.LANG.code}">${q ? esc(t === 'form' ? (q.prompt.prefix ? q.prompt.prefix + ' ' : '') + q.row.value : q.answer) : ''}</p>`;
