  A.acts.reveal = () => { const f = A.$('#flip'); if (f && !f.classList.contains('flipped')) reveal(null, null); };
  A.acts.gp = function (el) {
    const it = session.items[session.i], right = A.genderOf(it.w), ok = el.dataset.g === right;
    A.$$('.gp').forEach(b => { b.disabled = true; b.classList.toggle('right', b.dataset.g === right); b.classList.toggle('wrongpick', b === el && !ok); });
    reveal(ok ? 'Right' : 'Not quite', ok ? 2 : 0);
  };
  A.forms.typed = function (f, fd) {
    const it = session.items[session.i], q = it.q;
    const exp = it.t === 'form' ? q.row.value : q.answer;
    const res = A.checkAnswer(fd.get('a') || '', exp);
    reveal(A.verdictFor(res), res === 'right' ? 2 : res === 'accent' ? 2 : res === 'close' ? 1 : 0);
  };
  A.acts.grade = function (el) {
    const g = +el.dataset.g, it = session.items[session.i], { w, t } = it;
    const wasNew = !w.srs[t];
    w.srs[t] = A.schedule(w.srs[t], g);
    if (wasNew) A.bumpDay('new');
    A.bumpDay('reviews'); A.xp(g > 0 ? 2 : 1);
    if (g > 0) { A.bumpDay('correct'); session.right++; }
    A.recordCat(t === 'form' && it.q ? it.q.cat : t === 'gender' ? 'gender:' + A.genderOf(w) : t === 'mean' ? 'meaning' : t, g > 0);
    if (g === 0) session.items.splice(Math.min(session.items.length, session.i + 4), 0, { w, t });
    A.save(); session.i++; session.done++;
    A.routes.review();
  };
  function reviewDone() {
    const s = session || { done: 0, right: 0 };
    A.view().innerHTML = `<header class="top"><h1>${s.done ? 'Review done' : 'Nothing to review'}</h1></header>
      <section class="done-card">${s.done ? `${A.ring(s.right, s.done, 120, 'Remembered')}<p class="big-num">${Math.round(s.right / s.done * 100)}%</p><p class="muted">${s.done} cards. Next due ${A.nextDueText()}.</p>` : `<p class="muted">${A.db.words.length ? 'Everything is scheduled for later. Try a flash test.' : 'Add some words first.'}</p>`}
      <div class="row-btns"><a class="btn primary" href="#/today">Back to today</a><a class="btn" href="#/flash">Flash test</a></div></section>`;
    session = null;
  }
  A.acts.speak = el => A.speak(el.dataset.t);
  A.acts['open-url'] = el => A.openUrl(el.dataset.url);
  A.acts['sheet-close'] = () => A.closeSheet();
})();

