/* Views: practice (flash, drills, writing games), learn (grammar, phrases, reading, writing, tutor), progress, settings; boot */
(function () {
  'use strict';
  const A = window.App, G = A.G, esc = A.esc;

  // ---------------- shared multiple-choice quiz ----------------
  let quiz = null;
  A.runQuiz = function (opts) { quiz = Object.assign({ i: 0, right: 0, answered: false }, opts); renderQuiz(); };
  function renderQuiz() {
    const q = quiz.questions[quiz.i];
    if (!q) return quizDone();
    A.view().innerHTML = `<div class="review">
      <div class="rv-top"><a class="back" href="${quiz.back}">${esc(quiz.backLabel || 'Back')}</a><span class="rv-count">${quiz.i + 1} / ${quiz.questions.length}</span></div>
      <div class="progress"><span style="width:${quiz.i / quiz.questions.length * 100}%"></span></div>
      <article class="card quiz-card"><p class="cue">${esc(quiz.title)}</p><p class="quiz-q" lang="${A.LANG.code}">${q.html || esc(q.q)}</p>${q.hint ? `<p class="hint-box">💡 ${esc(q.hint)}</p>` : ''}${q.audio ? `<button class="mic-btn listen" data-act="speak" data-t="${esc(q.audio)}" aria-label="Play again">🔊</button>` : ''}
        <div class="options">${q.o.map((o, i) => `<button class="opt" data-act="quiz-pick" data-i="${i}" lang="${A.LANG.code}">${esc(o)}</button>`).join('')}</div>
        <div class="answer" hidden><p class="verdict"></p>${q.ex ? `<p class="ex-text">${esc(q.ex)}</p>` : ''}<div class="q-words"></div></div></article>
      <button class="btn primary wide" data-act="quiz-next" hidden>Next</button></div>`;
    if (q.audio) setTimeout(() => A.speak(q.audio), 350);
  }
  A.acts['quiz-pick'] = function (el) {
    if (quiz.answered) return; quiz.answered = true;
    const q = quiz.questions[quiz.i], i = +el.dataset.i, ok = i === q.a;
    A.$$('.opt').forEach((b, k) => { b.disabled = true; if (k === q.a) b.classList.add('right'); if (b === el && !ok) b.classList.add('wrong'); });
    if (ok) quiz.right++;
    if (q.onAnswer) q.onAnswer(ok);
    A.recordCat(q.cat || quiz.cat || 'grammar', ok); A.xp(ok ? 2 : 1); A.save();
    const ans = A.$('.answer'); ans.hidden = false;
    A.$('.verdict', ans).textContent = ok ? 'Right' : 'Not quite'; A.$('.verdict', ans).className = 'verdict ' + (ok ? 'ok' : 'bad');
    A.$('[data-act="quiz-next"]').hidden = false;
    quizWords(ans);
  };
  // after answering: the words in this question you don't have yet, one tap to add
  function quizWords(ans) {
    const box = A.$('.q-words', ans); if (!box) return;
    const qText = (A.$('.quiz-q') || {}).textContent || '', right = (A.$$('.opt')[quiz.questions[quiz.i].a] || {}).textContent || '';
    const sentence = qText.includes('___') ? qText.replace(/_{2,}/, right) : qText;
    const text = [sentence, right, (A.$('.ex-text', ans) || {}).textContent || ''].join(' ');
    const re = new RegExp(A.LANG.wordRe.source, 'g'), seen = new Set(), out = [];
    (text.match(re) || []).forEach(tok => {
      const h = A.lookupForm(tok).find(x => x.kind === 'dict'); if (!h) return;
      const e = h.e; if (seen.has(e.lemma) || A.findByLemma(e.lemma) || (e.pos === 'other' && e.lemma.length <= 4)) return;
      seen.add(e.lemma); out.push(e);
    });
    if (!out.length) return;
    const ctx = /[.;!?]/.test(sentence) && new RegExp(A.LANG.wordRe.source).test(sentence) ? sentence.trim().slice(0, 220) : '';
    box.innerHTML = `<p class="tiny">New words here. Tap to add them to your words:</p><div class="chips wrap">${out.slice(0, 6).map(e => `<button class="chip q-add" data-act="quiz-add" data-l="${esc(e.lemma)}" data-ctx="${esc(ctx)}"><b lang="${A.LANG.code}">+ ${esc(A.entryHead(e))}</b> ${esc(e.meaning.split(/[;,]/)[0])}</button>`).join('')}</div>`;
  }
  A.acts['quiz-add'] = function (el) {
    if (el.classList.contains('done')) return;
    const e = A.dict.find(x => x.lemma === el.dataset.l); if (!e) return;
    if (!A.findByLemma(e.lemma)) { const w = A.entryToWord(e, el.dataset.ctx ? { examples: [{ text: el.dataset.ctx, source: 'Test' }] } : {}); A.db.words.push(w); A.save(); A.resetIndex(); A.xp(1); }
    el.classList.add('done'); el.innerHTML = `✓ ${esc(A.entryHead(e))} added`;
  };
  A.acts['quiz-next'] = () => { quiz.i++; quiz.answered = false; renderQuiz(); };
  function quizDone() {
    const pct = Math.round(quiz.right / quiz.questions.length * 100);
    if (quiz.onDone) quiz.onDone(quiz.right, quiz.questions.length);
    A.save();
    A.view().innerHTML = `<header class="top"><h1>${quiz.right} / ${quiz.questions.length}</h1></header>
      <section class="done-card">${A.ring(quiz.right, quiz.questions.length, 120, 'Score')}<p class="big-num">${pct}%</p><p class="muted">${pct >= 80 ? 'Excellent.' : pct >= 50 ? 'Good work. Try it again tomorrow.' : 'This one needs more practice. The tips will come up again.'}</p>
      <div class="row-btns">${quiz.retry ? `<button class="btn primary" data-act="quiz-retry">Try again</button>` : ''}<a class="btn" href="${quiz.back}">${esc(quiz.backLabel || 'Back')}</a></div></section>`;
  }
  A.acts['quiz-retry'] = () => { const r = quiz.retry; r(); };

  // ---------------- PRACTICE HUB ----------------
  A.routes.practice = function () {
    const best = A.db.stats.best.flash || 0;
    A.view().innerHTML = `
      <header class="top"><h1>Practice</h1><p class="muted">Quick rounds that build speed and accuracy. Everything feeds your weak spots.</p></header>
      <a href="#/daily" class="feature t-sun"><span class="f-ico">📝</span><span class="f-text"><strong>Today's test</strong><small>${A.dailyDone() ? `Done: ${A.dailyDone().score}/${A.dailyDone().total}. Practice round available.` : '12 mixed questions: your words, listening, phrases, forms.'}</small></span></a>
      <a href="#/games" class="feature t-games"><span class="f-ico">🎮</span><span class="f-text"><strong>Games</strong><small>Word Rain, Memory pairs and ${{ el: 'Λεξούλα', es: 'Palabrita', fr: 'Motus' }[A.LANG.code] || 'the daily word'}.</small></span></a>
      <a href="#/flash" class="feature t-sea"><span class="f-ico">⚡</span><span class="f-text"><strong>Flash test</strong><small>90 seconds of rapid-fire questions: words, articles, verb forms, phrases.${best ? ` Best: ${best}` : ''}</small></span></a>
      <div class="tile-grid">
        ${A.LANG.alphabet ? '<a href="#/alphabet" class="tile"><span class="glyph">Αα</span><strong>Alphabet</strong><small>Letters and sounds</small></a>' : ''}
        ${A.LANG.code === 'el' ? '<a href="#/cases" class="tile"><span class="glyph">τον</span><strong>Cases trainer</strong><small>Articles and endings in real sentences</small></a><a href="#/casespot" class="tile" data-act="cs-start" data-c=""><span class="glyph">🔎</span><strong>Case spotter</strong><small>Which case is each word?</small></a>' : ''}
        <a href="#/articles" class="tile"><span class="arts">${G.GENDERS.map(g => `<b class="g-${g}">${G.G_TO_ART[g]}</b>`).join('')}</span><strong>Article sprint</strong><small>60 seconds of gender</small></a>
        <a href="#/forms/weak" class="tile"><span class="glyph">🎯</span><strong>Weak spots</strong><small>Forms you miss most</small></a>
        <a href="#/forms/verbs" class="tile"><span class="glyph">${{ el: '-ω', es: '-ar', fr: '-er' }[A.LANG.code] || '→'}</span><strong>Verb forms</strong><small>Pick tenses, type forms</small></a>
        <a href="#/forms/nouns" class="tile"><span class="glyph">${A.LANG.code === 'el' ? '-ου' : '+s'}</span><strong>${A.LANG.code === 'el' ? 'Noun cases' : 'Plurals & agreement'}</strong><small>${A.LANG.code === 'el' ? 'Genitives and plurals' : 'Nouns and adjectives'}</small></a>
        <a href="#/vocab" class="tile"><span class="glyph">${{ el: 'Αα', es: 'Ññ', fr: 'Éé' }[A.LANG.code] || 'Aa'}</span><strong>Vocab quiz</strong><small>Your words + dictionary</small></a>
        <a href="#/forms/irregular" class="tile"><span class="glyph irr-g">!</span><strong>Irregulars</strong><small>The rule-breakers</small></a>
        <a href="#/scramble" class="tile"><span class="glyph">⇄</span><strong>Word order</strong><small>Unscramble sentences</small></a>
        <a href="#/translate" class="tile"><span class="glyph">✍️</span><strong>Translate</strong><small>English → ${A.LANG.name}</small></a>
        <a href="#/dictation" class="tile"><span class="glyph">🎧</span><strong>Dictation</strong><small>Listen and type</small></a>
        <a href="#/speak" class="tile"><span class="glyph">🎙️</span><strong>Speak</strong><small>Say it, get a score</small></a>
        <a href="#/badges" class="tile"><span class="glyph">🏅</span><strong>Badges</strong><small>Streak, level, trophies</small></a>
        <a href="#/aitest" class="tile ai"><span class="glyph">✨</span><strong>${A.AI} test</strong><small>A test made from your words</small></a>
      </div>`;
  };

  // pools for generated questions
  function wordPool() {
    const mine = A.db.words.filter(w => w.meaning);
    const dict = A.stageDict().filter(e => e.pos !== 'other' || e.tag === 'adv' || A.stageLevel() === 1).map(e => ({ lemma: e.lemma, meaning: e.meaning, pos: e.pos, gender: e.gender || '', emoji: e.emoji, _e: e }));
    return { mine, dict };
  }
  function pickWord(pred) {
    const { mine, dict } = wordPool();
    const m = mine.filter(pred || (() => true)), d = dict.filter(pred || (() => true));
    if (m.length >= 6 && Math.random() < 0.65) return A.pick(m);
    return A.pick(d.length ? d : m);
  }
  const headOf = w => A.artJoin(w.lemma, w.gender || A.genderOf(w)) + w.lemma;
  function distract(correct, pool, key, n) {
    const out = new Set([correct]); let tries = 0;
    while (out.size < (n || 4) && tries++ < 60) { const x = A.pick(pool)[key]; if (x && x !== correct) out.add(x); }
    return A.shuffle(Array.from(out));
  }
  function genQuestion(kinds) {
    const k = A.pick(kinds || ['gr', 'gr', 'en', 'art', 'form', 'phrase']);
    const { mine, dict } = wordPool();
    const all = mine.concat(dict);
    if (k === 'gr' || k === 'en') {
      const w = pickWord();
      if (k === 'gr') { const o = distract(w.meaning, all, 'meaning'); return { kind: k, q: (w.emoji ? w.emoji + ' ' : '') + headOf(w), sub: 'What does it mean?', o, a: o.indexOf(w.meaning), cat: 'vocab' }; }
      const o = distract(headOf(w), all.map(x => ({ h: headOf(x) })), 'h'); return { kind: k, q: w.meaning, sub: `Which ${A.LANG.name} word?`, o, a: o.indexOf(headOf(w)), cat: 'vocab', en: true };
    }
    if (k === 'art') {
      const w = pickWord(x => x.pos === 'noun' && !/\(ο\/η\)/.test(x.meaning || '') && (x.gender || A.genderOf(x)) && !/'$/.test(A.art(x.lemma, x.gender || A.genderOf(x))) && !/\s/.test(x.lemma));
      const g = w.gender || A.genderOf(w);
      return { kind: k, q: (w.emoji ? w.emoji + ' ' : '') + w.lemma, sub: 'Which article?', o: G.GENDERS.map(x => G.G_TO_ART[x]), a: G.GENDERS.indexOf(g), cat: 'gender:' + g };
    }
    if (k === 'form') {
      for (let t = 0; t < 8; t++) {
        let w = pickWord(x => x.pos === 'verb');
        if (w._e) w = A.entryToWord(w._e);
        const fq = A.formQuestion(w, { tenses: A.stageTenses().filter(t => t !== 'imperative') });
        if (!fq) continue;
        const vals = Array.from(new Set(A.allRows(w).map(r => r.value).filter(v => v && v !== fq.row.value)));
        if (vals.length < 3) continue;
        const o = A.shuffle([fq.row.value].concat(A.shuffle(vals).slice(0, 3)));
        return { kind: k, q: fq.prompt.head, sub: fq.prompt.detail, hint: fq.prompt.hint, o, a: o.indexOf(fq.row.value), cat: fq.cat };
      }
      return genQuestion(['gr', 'art']);
    }
    const sp = A.stagePhrases();
    const p = A.pick(sp);
    const same = sp.filter(x => x.topic === p.topic);
    const o = distract(p.gr, same.length > 4 ? same : sp, 'gr');
    return { kind: 'phrase', q: p.en, sub: 'Which is right?', o, a: o.indexOf(p.gr), cat: 'phrase', en: true };
  }

  // ---------------- FLASH TEST ----------------
  let flash = null, flashTimer = null;
  A.routes.flash = function () {
    if (!flash || flash.over) {
      const best = A.db.stats.best.flash || 0;
      A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Flash test</h1>
        <p class="muted">90 seconds. Tap fast: right answers in a row build a combo multiplier. Mixes your words with the dictionary.</p></header>
        ${flash && flash.over ? `<section class="done-card flash-done"><p class="big-num">${flash.score}</p><p class="muted">${flash.right} right · ${flash.n - flash.right} wrong · best combo ×${flash.maxCombo}</p>${flash.score >= best && flash.score > 0 ? '<p class="new-best">New best!</p>' : `<p class="tiny">Best: ${best}</p>`}
          ${flash.misses.length ? `<h2>Review these</h2><ul class="miss-list">${flash.misses.slice(0, 8).map(m => `<li><span lang="${A.LANG.code}">${esc(m.q)}</span> → <b lang="${A.LANG.code}">${esc(m.ans)}</b></li>`).join('')}</ul>` : ''}</section>` : ''}
        <button class="btn primary wide big" data-act="flash-start">${flash && flash.over ? 'Go again' : 'Start'}</button>`;
      return;
    }
    const q = flash.q;
    A.view().innerHTML = `<div class="review flash">
      <div class="rv-top"><a class="back" href="#/practice" data-act="flash-stop">Stop</a><span class="combo ${flash.combo >= 3 ? 'hot' : ''}">×${comboMult()}</span><span class="rv-count" id="ftime">${flash.left}s</span></div>
      <div class="progress time"><span id="fbar" style="width:${flash.left / 90 * 100}%"></span></div>
      <article class="card flash-card"><p class="cue">${esc(q.sub)}</p>${q.hint ? `<p class="hint-box sm">💡 ${esc(q.hint)}</p>` : ''}<p class="flash-q" ${q.en ? '' : `lang="${A.LANG.code}"`}>${esc(q.q)}</p></article>
      <div class="options ${q.kind === 'art' ? 'arts3' : ''}">${q.o.map((o, i) => `<button class="opt ${q.kind === 'art' ? 'g-' + G.GENDERS[i] : ''}" data-act="flash-pick" data-i="${i}" lang="${A.LANG.code}">${esc(o)}</button>`).join('')}</div>
      <p class="flash-score">${flash.score} pts</p></div>`;
  };
  const comboMult = () => flash.combo >= 10 ? 4 : flash.combo >= 6 ? 3 : flash.combo >= 3 ? 2 : 1;
  A.acts['flash-start'] = function () {
    flash = { left: 90, score: 0, n: 0, right: 0, combo: 0, maxCombo: 0, misses: [], over: false, q: genQuestion() };
    clearInterval(flashTimer);
    flashTimer = setInterval(() => {
      if (!flash || flash.over) return clearInterval(flashTimer);
      flash.left--;
      const t = A.$('#ftime'); if (t) t.textContent = flash.left + 's';
      const b = A.$('#fbar'); if (b) b.style.width = (flash.left / 90 * 100) + '%';
      if (flash.left <= 0) endFlash();
    }, 1000);
    A.routes.flash();
  };
  function endFlash() {
    clearInterval(flashTimer); flash.over = true;
    if (flash.score > (A.db.stats.best.flash || 0)) A.db.stats.best.flash = flash.score;
    A.save(); if ((location.hash || '').startsWith('#/flash')) A.routes.flash();
  }
  A.acts['flash-stop'] = () => { clearInterval(flashTimer); flash = null; };
  A.acts['flash-pick'] = function (el) {
    if (!flash || flash.locked) return;
    const q = flash.q, ok = +el.dataset.i === q.a;
    flash.n++; flash.locked = true;
    if (ok) { flash.right++; flash.combo++; flash.maxCombo = Math.max(flash.maxCombo, flash.combo); flash.score += 10 * comboMult(); el.classList.add('right'); }
    else { flash.combo = 0; el.classList.add('wrong'); A.$$('.opt')[q.a].classList.add('right'); flash.misses.push({ q: q.q, ans: q.o[q.a] }); }
    A.recordCat(q.cat, ok); A.xp(ok ? 1 : 0); A.save();
    setTimeout(() => { if (!flash || flash.over) return; flash.locked = false; flash.q = genQuestion(); A.routes.flash(); }, ok ? 250 : 900);
  };

  // ---------------- VOCAB QUIZ ----------------
  A.routes.vocab = function () {
    const qs = []; for (let i = 0; i < 10; i++) { const q = genQuestion(['gr', 'en', 'gr', 'art']); qs.push({ q: q.q, o: q.o, a: q.a, cat: q.cat, ex: '', html: `<span class="q-sub">${esc(q.sub)}</span><br>${esc(q.q)}` }); }
    A.runQuiz({ title: 'Vocabulary', questions: qs, back: '#/practice', backLabel: 'Practice', retry: () => A.routes.vocab() });
  };

  // ---------------- ARTICLE SPRINT ----------------
  let sprint = null, sprintTimer = null;
  A.routes.articles = function () {
    if (!sprint || sprint.over) {
      A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Article sprint</h1><p class="muted">60 seconds. A noun appears; tap ${G.GENDERS.map(g => G.G_TO_ART[g]).join(' or ')}. Uses your nouns and the dictionary.</p></header>
        ${sprint && sprint.over ? `<section class="done-card"><p class="big-num">${sprint.right}<small> / ${sprint.n}</small></p>${sprint.misses.length ? `<p class="muted">Missed:</p><div class="chips wrap">${sprint.misses.map(w => `<span class="chip g-${w.g}" lang="${A.LANG.code}">${esc(A.artJoin(w.lemma, w.g) + w.lemma)}</span>`).join('')}</div>` : '<p class="muted">No misses.</p>'}</section>` : ''}
        <button class="btn primary wide big" data-act="art-start">${sprint && sprint.over ? 'Go again' : 'Start'}</button>`;
      return;
    }
    const w = sprint.cur;
    A.view().innerHTML = `<div class="review sprint"><div class="rv-top"><a class="back" href="#/practice" data-act="art-stop">Stop</a><span class="rv-count" id="timer">${sprint.left}s</span></div>
      <article class="card sprint-card"><p class="card-word" lang="${A.LANG.code}">${w.emoji ? `<span class="emo big">${w.emoji}</span>` : ''}<span class="lemma">${esc(w.lemma)}</span></p><p class="muted">${esc(w.meaning)}</p></article>
      <div class="gender-pick big g${G.GENDERS.length}">${G.GENDERS.map(g => `<button class="gp g-${g}" data-act="art-pick" data-g="${g}">${G.G_TO_ART[g]}</button>`).join('')}</div>
      <p class="flash-score">${sprint.right} right</p></div>`;
  };
  function nounPool() {
    const ok = (l, g) => !/\s/.test(l) && !/'$/.test(A.art(l, g));
    const mine = A.db.words.filter(w => w.pos === 'noun' && A.genderOf(w) && ok(w.lemma, A.genderOf(w))).map(w => ({ lemma: w.lemma, meaning: w.meaning, g: A.genderOf(w), emoji: w.emoji }));
    const dict = A.stageDict().filter(e => e.pos === 'noun' && !/\(ο\/η\)/.test(e.meaning) && ok(e.lemma, e.gender) && !/\(pl/.test(e.meaning)).map(e => ({ lemma: e.lemma, meaning: e.meaning, g: e.gender, emoji: e.emoji }));
    return mine.length >= 8 && Math.random() < 0.6 ? mine : dict;
  }
  A.acts['art-start'] = function () {
    sprint = { left: 60, n: 0, right: 0, misses: [], again: [], over: false, cur: A.pick(nounPool()) };
    clearInterval(sprintTimer);
    sprintTimer = setInterval(() => {
      if (!sprint || sprint.over) return clearInterval(sprintTimer);
      sprint.left--; const t = A.$('#timer'); if (t) t.textContent = sprint.left + 's';
      if (sprint.left <= 0) { clearInterval(sprintTimer); sprint.over = true; A.save(); if ((location.hash || '').startsWith('#/articles')) A.routes.articles(); }
    }, 1000);
    A.routes.articles();
  };
  A.acts['art-stop'] = () => { clearInterval(sprintTimer); sprint = null; };
  A.acts['art-pick'] = function (el) {
    if (!sprint || sprint.locked) return;
    const w = sprint.cur, ok = el.dataset.g === w.g;
    sprint.n++; sprint.locked = true;
    if (ok) sprint.right++; else { if (!sprint.misses.find(x => x.lemma === w.lemma)) sprint.misses.push(w); sprint.again.push(w); }
    A.recordCat('gender:' + w.g, ok); A.xp(ok ? 1 : 0); A.save();
    el.classList.add(ok ? 'right' : 'wrongpick');
    if (!ok) A.$(`.gp[data-g="${w.g}"]`).classList.add('right');
    setTimeout(() => {
      if (!sprint || sprint.over) return;
      sprint.locked = false;
      sprint.cur = sprint.again.length && Math.random() < 0.35 ? sprint.again.shift() : A.pick(nounPool());
      A.routes.articles();
    }, ok ? 200 : 700);
  };

  // ---------------- FORMS DRILL ----------------
  let drill = null;
  A.routes.forms = function (mode) {
    mode = mode || 'weak';
    if (!drill || drill.mode !== mode) drill = { mode, tenses: A.stageTenses().slice(0, 4), n: 0, right: 0, q: null, started: mode === 'word', wordId: drill && drill.wordId };
    const pool = formsPool(mode);
    const titles = { weak: 'Weak spots', verbs: 'Verb forms', nouns: A.LANG.code === 'el' ? 'Noun cases' : 'Plurals & agreement', irregular: 'Irregulars only', word: 'Word drill' };
    if (!pool.length) { A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>${titles[mode]}</h1></header><p class="empty">No words for this drill yet.</p>`; return; }
    if (!drill.started) {
      const weak = weakCats().slice(0, 4);
      A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>${titles[mode]}</h1><p class="muted">Rounds of 10. Type each form, or switch to multiple choice at the top.${mode !== 'irregular' && A.db.words.length < 10 ? ' Uses dictionary words too until you have more of your own.' : ''}</p></header>
        ${mode !== 'nouns' ? `<p class="label">Tenses</p><div class="chips wrap">${A.stageTenses().map(t => `<button class="chip ${drill.tenses.includes(t) ? 'on' : ''}" data-act="tense" data-t="${t}">${esc(G.TENSE_LABEL[t].split(' (')[0])}</button>`).join('')}</div>${drill.tenses.map(t => (G.TENSE_HINT || {})[t] ? `<p class="tiny">• <b>${esc(G.TENSE_LABEL[t].split(' (')[0])}</b>: ${esc(G.TENSE_HINT[t].what)} ("${esc(G.TENSE_HINT[t].ex[0] || G.TENSE_HINT[t].ex[1])}")</p>` : '').join('')}` : ''}
        ${mode === 'weak' ? (weak.length ? `<p class="label">Your weakest areas</p><ul class="weak">${weak.map(c => `<li><span>${esc(A.CAT_LABEL[c.cat] || c.cat)}</span><b>${Math.round(c.acc * 100)}%</b></li>`).join('')}</ul>` : `<p class="muted">Do some reviews or drills first and this will focus on what you miss.</p>`) : ''}
        <button class="btn primary wide big" data-act="forms-start">Start</button>`;
      return;
    }
    if (drill.n >= 10 && !drill.q) {
      A.view().innerHTML = `<header class="top"><h1>${drill.right} / 10</h1></header><section class="done-card">${A.ring(drill.right, 10, 120, 'Score')}<p class="muted">${drill.right >= 8 ? 'Strong round.' : drill.right >= 5 ? 'Getting there.' : 'These will come up more often.'}</p>
        <div class="row-btns"><button class="btn primary" data-act="forms-again">Another round</button><a class="btn" href="#/practice">Done</a></div></section>`;
      return;
    }
    if (!drill.q) drill.q = nextFormQ(pool, mode);
    const q = drill.q;
    if (!q) { A.view().innerHTML = `<p class="empty">No forms match these tenses. <a href="#/practice">Back</a></p>`; return; }
    const choice = !!A.global.drillChoice;
    if (choice && !q._opts) { const d = drillOptions(q); q._opts = d.opts; q._right = d.right; }
    A.view().innerHTML = `<div class="review"><div class="rv-top"><a class="back" href="#/practice">Stop</a><div class="seg mini" role="radiogroup" aria-label="Answer mode"><button class="${choice ? '' : 'on'}" data-act="drill-mode" data-v="type">Type</button><button class="${choice ? 'on' : ''}" data-act="drill-mode" data-v="choice">Choose</button></div><span class="rv-count">${drill.n + 1} / 10</span></div>
      <div class="progress"><span style="width:${drill.n * 10}%"></span></div>
      <article class="card g-card-${A.genderOf(q.w) || 'x'}"><p class="cue">${esc(q.prompt.detail)}</p>${q.prompt.hint ? `<p class="hint-box">💡 ${esc(q.prompt.hint)}</p>` : ''}<p class="card-word" lang="${A.LANG.code}">${esc(q.prompt.head)}</p><p class="muted">${esc(q.w.meaning)}</p>
      ${choice ? `<div class="options drill-opts">${q._opts.map((o, i) => `<button class="opt" data-act="drill-pick" data-i="${i}" lang="${A.LANG.code}">${esc(o)}</button>`).join('')}</div>` : `<form data-form="drill" class="typed"><input name="a" lang="${A.LANG.code}" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the form (article optional)">${A.canListen() ? '<button type="button" class="icon-btn mic" data-act="mic-fill" aria-label="Say it">🎙️</button>' : ''}<button class="btn primary" type="submit">Check</button></form>`}
      <div class="answer" hidden><p class="verdict"></p><p class="card-word sm" lang="${A.LANG.code}">${esc((q.prompt.prefix ? q.prompt.prefix + ' ' : '') + q.row.value)}</p></div></article>
      <button class="btn primary wide" data-act="drill-next" hidden>Next</button></div>`;
    { const ti = A.$('.typed input'); if (ti) ti.focus(); }
  };
  function formsPool(mode) {
    let ws = A.db.words.filter(w => A.tableFor(w));
    if (mode === 'word') return ws.filter(w => w.id === drill.wordId);
    if (mode === 'irregular') return ws.filter(A.isIrregular).concat(A.stageDict().filter(e => e.ov && (e.ov.aorist || e.ov.stem)).map(e => A.entryToWord(e))).concat(A.stageDict().filter(e => e.pos === 'verb' && G.guessVerbGroup(e.lemma) === 'IRR').map(e => A.entryToWord(e)));
    if (ws.length < 10) ws = ws.concat(A.shuffle(A.stageDict().filter(e => e.pos === 'verb' || (e.pos === 'noun' && !/\s/.test(e.lemma)))).slice(0, 60).map(e => A.entryToWord(e)).filter(w => A.tableFor(w)));
    if (mode === 'verbs') ws = ws.filter(w => w.pos === 'verb');
    if (mode === 'nouns') ws = ws.filter(w => w.pos === 'noun' || w.pos === 'adj');
    return ws;
  }
  const weakCats = () => Object.entries(A.db.stats.cats).filter(([, v]) => v.n >= 3).map(([cat, v]) => ({ cat, acc: v.c / v.n, n: v.n })).sort((a, b) => a.acc - b.acc);
  function nextFormQ(pool, mode) {
    const filter = { tenses: drill.tenses, irregularCells: mode === 'irregular' };
    if (mode === 'weak') { const weak = weakCats().slice(0, 3).map(c => c.cat); for (let k = 0; k < 14; k++) { const q = A.formQuestion(A.pick(pool), filter); if (q && (!weak.length || weak.includes(q.cat) || k > 10)) return q; } }
    for (let k = 0; k < 12; k++) { const q = A.formQuestion(A.pick(pool), filter); if (q) return q; }
    return null;
  }
  A.acts['drill-word'] = el => { drill = { mode: 'word', wordId: el.dataset.id, tenses: A.stageTenses().slice(), n: 0, right: 0, q: null, started: true }; A.go('#/forms/word'); };
  A.acts.tense = el => { const t = el.dataset.t; drill.tenses = drill.tenses.includes(t) ? drill.tenses.filter(x => x !== t) : drill.tenses.concat(t); if (!drill.tenses.length) drill.tenses = [t]; A.routes.forms(drill.mode); };
  A.acts['forms-start'] = () => { Object.assign(drill, { started: true, n: 0, right: 0, q: null }); A.routes.forms(drill.mode); };
  A.acts['forms-again'] = () => { Object.assign(drill, { n: 0, right: 0, q: null }); A.routes.forms(drill.mode); };
  A.acts['drill-next'] = () => { drill.n++; drill.q = null; A.routes.forms(drill.mode); };
  A.forms.drill = function (f, fd) {
    const q = drill.q, res = A.checkAnswer(fd.get('a') || '', q.row.value);
    drillResult(res, f);
  };
  function drillResult(res, f) {
    const q = drill.q, ok = A.answerOk(res);
    if (ok) drill.right++;
    A.recordCat(q.cat, ok); A.xp(ok ? 2 : 1); A.save();
    if (f) A.$$('input,button', f).forEach(x => x.disabled = true);
    const a = A.$('.answer'); a.hidden = false;
    const v = A.$('.verdict', a); v.textContent = A.verdictFor(res); v.className = 'verdict ' + (res === 'right' ? 'ok' : ok || res === 'close' ? 'mid' : 'bad');
    const nb = A.$('[data-act="drill-next"]'); nb.hidden = false; nb.focus();
  }
  // multiple-choice version: the right form plus other forms of the same word
  function drillOptions(q) {
    const full = r => (r.prefix ? r.prefix + ' ' : '') + r.value;
    const right = full(q.row);
    let rows = A.allRows(q.w, true).filter(r => r.value && r.key !== q.row.key && (q.w.pos === 'verb' || !r.key.endsWith('.voc') || q.row.key.endsWith('.voc')));
    if (q.row.key.endsWith('.voc')) rows = rows.filter(r => r.key.endsWith('.voc') || !r.prefix).concat(rows.filter(r => r.prefix).map(r => Object.assign({}, r, { prefix: '' })));
    if (q.w.pos === 'verb') { const t = q.row.key.split('.')[0]; const same = rows.filter(r => r.key.startsWith(t + '.')); const other = rows.filter(r => !r.key.startsWith(t + '.')); rows = A.shuffle(same).slice(0, 2).concat(A.shuffle(other)); }
    else rows = A.shuffle(rows);
    const opts = [right];
    rows.forEach(r => { const o = full(r); if (opts.length < 4 && !opts.some(x => G.strip(x) === G.strip(o))) opts.push(o); });
    return { opts: A.shuffle(opts), right };
  }
  A.acts['drill-mode'] = el => { A.global.drillChoice = el.dataset.v === 'choice'; A.saveGlobal(); if (drill.q) drill.q._opts = null; A.routes.forms(drill.mode); };
  A.acts['drill-pick'] = function (el) {
    if (drill.q._answered) return; drill.q._answered = true;
    const right = drill.q._opts.indexOf(drill.q._right), ok = +el.dataset.i === right;
    A.$$('.drill-opts .opt').forEach((b, k) => { b.disabled = true; if (k === right) b.classList.add('right'); if (b === el && !ok) b.classList.add('wrong'); });
    drillResult(ok ? 'right' : 'wrong');
  };

  // ---------------- SENTENCE GAMES: scramble, translate, dictation ----------------
  function sentencePool(minWords) {
    const PH = A.stagePhrases();
    const mine = A.db.words.flatMap(w => (w.examples || []).filter(e => e.text && e.text.split(/\s+/).length >= minWords).map(e => ({ gr: e.text, en: w.meaning ? `(uses ${w.lemma}: ${w.meaning})` : '' })));
    const ph = PH.filter(p => p.gr.split(/\s+/).length >= minWords);
    return mine.length >= 5 && Math.random() < 0.3 ? mine : ph;
  }
  let game = null;
  A.routes.scramble = function () {
    if (!game || game.kind !== 'scramble' || game.done) { const p = A.pick(sentencePool(3)); const words = p.gr.replace(/[.!;?,]$/, '').split(/\s+/); game = { kind: 'scramble', p, words, pool: A.shuffle(words.map((w, i) => ({ w, i }))), built: [], n: (game && game.kind === 'scramble' ? game.n : 0), done: false }; if (game.pool.map(x => x.i).join() === words.map((_, i) => i).join()) game.pool.reverse(); }
    const g = game;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Word order</h1></header>
      <article class="card"><p class="cue">Put the words in order</p><p class="en-prompt">${esc(g.p.en)}</p>
        <div class="built" id="built">${g.built.map((x, k) => `<button class="token on" data-act="sc-back" data-k="${k}" data-from="built" lang="${A.LANG.code}">${esc(x.w)}</button>`).join('') || '<span class="tiny">Tap the words below, or drag them into place</span>'}</div>
        <div class="tokens" id="pool">${g.pool.map((x, k) => `<button class="token" data-act="sc-take" data-k="${k}" data-from="pool" lang="${A.LANG.code}">${esc(x.w)}</button>`).join('')}</div>
        ${g.built.length && g.pool.length ? '<p class="tiny">Missed a word? Drag it to the right place in the sentence. You can drag words around in the sentence too.</p>' : ''}
        <div class="answer" hidden><p class="verdict"></p><p class="card-ex" lang="${A.LANG.code}">${esc(g.p.gr)}</p></div></article>
      <div class="row-btns split"><button class="btn ghost" data-act="sc-skip">Skip</button><button class="btn" data-act="speak" data-t="${esc(g.p.gr)}">🔊</button><button class="btn primary push" data-act="sc-check" ${g.pool.length ? 'disabled' : ''}>Check</button></div>`;
  };
  // drag and drop for the word tokens (touch and mouse): drop into the sentence at any position, or back into the pool
  (function () {
    let drag = null, swallow = false;
    const insertIndex = (x, y) => {
      const toks = A.$$('#built .token:not(.dragging)');
      for (let k = 0; k < toks.length; k++) {
        const r = toks[k].getBoundingClientRect();
        if (y < r.top) return k;
        if (y <= r.bottom && x < r.left + r.width / 2) return k;
      }
      return toks.length;
    };
    const inside = (el, x, y, pad) => { if (!el) return false; const r = el.getBoundingClientRect(); return x >= r.left - pad && x <= r.right + pad && y >= r.top - pad && y <= r.bottom + pad; };
    document.addEventListener('pointerdown', e => {
      const t = e.target.closest('.token[data-from]');
      if (!t || !game || game.kind !== 'scramble' || game.done) return;
      drag = { t, from: t.dataset.from, k: +t.dataset.k, x0: e.clientX, y0: e.clientY, on: false, id: e.pointerId };
    });
    document.addEventListener('pointermove', e => {
      if (!drag || e.pointerId !== drag.id) return;
      if (!drag.on) {
        if (Math.hypot(e.clientX - drag.x0, e.clientY - drag.y0) < 8) return;
        drag.on = true;
        const r = drag.t.getBoundingClientRect();
        drag.dx = drag.x0 - r.left; drag.dy = drag.y0 - r.top;
        drag.ghost = drag.t.cloneNode(true); drag.ghost.classList.add('ghost-token'); drag.ghost.style.width = r.width + 'px';
        document.body.appendChild(drag.ghost);
        drag.t.classList.add('dragging');
        drag.mark = document.createElement('span'); drag.mark.className = 'drop-mark';
      }
      e.preventDefault();
      drag.ghost.style.transform = `translate(${e.clientX - drag.dx}px, ${e.clientY - drag.dy}px)`;
      const built = A.$('#built');
      if (inside(built, e.clientX, e.clientY, 24)) {
        const toks = A.$$('#built .token:not(.dragging)'), i = insertIndex(e.clientX, e.clientY);
        const hint = A.$('#built .tiny'); if (hint) hint.remove();
        if (i < toks.length) built.insertBefore(drag.mark, toks[i]); else built.appendChild(drag.mark);
      } else if (drag.mark.parentNode) drag.mark.remove();
    }, { passive: false });
    const end = e => {
      if (!drag || e.pointerId !== drag.id) return;
      const d = drag; drag = null;
      if (!d.on) return;
      swallow = true; setTimeout(() => { swallow = false; }, 50);
      d.ghost.remove(); if (d.mark.parentNode) d.mark.remove();
      if (e.type === 'pointercancel') { A.routes.scramble(); return; }
      const g = game, x = e.clientX, y = e.clientY;
      const item = (d.from === 'pool' ? g.pool : g.built)[d.k];
      if (inside(A.$('#built'), x, y, 24)) {
        let i = insertIndex(x, y);
        if (d.from === 'built') g.built.splice(d.k, 1); else g.pool.splice(d.k, 1);
        g.built.splice(Math.min(i, g.built.length), 0, item);
      } else if (inside(A.$('#pool'), x, y, 30) && d.from === 'built') {
        g.built.splice(d.k, 1); g.pool.push(item);
      }
      A.routes.scramble();
    };
    document.addEventListener('pointerup', end);
    document.addEventListener('pointercancel', end);
    document.addEventListener('click', e => { if (swallow) { swallow = false; e.preventDefault(); e.stopImmediatePropagation(); } }, true);
  })();
  A.acts['sc-take'] = el => { const x = game.pool.splice(+el.dataset.k, 1)[0]; game.built.push(x); A.routes.scramble(); };
  A.acts['sc-back'] = el => { const x = game.built.splice(+el.dataset.k, 1)[0]; game.pool.push(x); A.routes.scramble(); };
  A.acts['sc-skip'] = () => { game.done = true; A.routes.scramble(); };
  A.acts['sc-check'] = function () {
    const ok = game.built.map(x => G.strip(x.w)).join(' ') === game.words.map(w => G.strip(w)).join(' ');
    A.recordCat('scramble', ok); A.xp(ok ? 3 : 1); A.save();
    const a = A.$('.answer'); a.hidden = false; const v = A.$('.verdict', a); v.textContent = ok ? 'Right!' : 'Not quite. Correct order:'; v.className = 'verdict ' + (ok ? 'ok' : 'bad');
    if (ok) A.speak(game.p.gr);
    game.done = true;
    const btn = A.$('[data-act="sc-check"]'); btn.textContent = 'Next'; btn.dataset.act = 'sc-skip'; btn.disabled = false;
  };

  A.routes.translate = function () {
    if (!game || game.kind !== 'translate' || game.done) game = { kind: 'translate', p: A.pick(A.stagePhrases().filter(p => p.gr.split(/\s+/).length >= 2)), done: false };
    const g = game;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Translate</h1></header>
      <article class="card"><p class="cue">${esc(g.p.topic)} · say it in ${A.LANG.name}</p><p class="en-prompt big">${esc(g.p.en)}</p>
        <form data-form="translate"><textarea name="a" rows="2" lang="${A.LANG.code}" autocapitalize="off" spellcheck="false" placeholder="${esc(A.LANG.writePlaceholder)}"></textarea><div class="row-btns"><button class="btn primary" type="submit">Check</button>${A.canListen() ? '<button type="button" class="btn" data-act="mic-fill">🎙️ Say it</button>' : ''}<button type="button" class="btn ghost" data-act="tr-skip">Skip</button></div></form>
        <div class="answer" hidden></div></article>`;
  };
  A.forms.translate = async function (f, fd) {
    const given = (fd.get('a') || '').trim(); if (!given) return;
    const g = game, sim = A.similarity(given, g.p.gr), ok = sim >= 0.9;
    A.recordCat('translate', ok); A.xp(ok ? 3 : 1); A.save();
    const a = A.$('.answer'); a.hidden = false;
    a.innerHTML = `<p class="verdict ${ok ? 'ok' : sim > 0.7 ? 'mid' : 'bad'}">${ok ? 'Spot on' : sim > 0.7 ? 'Close' : 'Here\'s one way to say it'}</p>
      <p class="card-ex" lang="${A.LANG.code}">${A.diffWords(given, g.p.gr)}</p><p class="tiny">Highlighted words are ones you didn't use. Other correct wordings are possible.</p>
      <div class="row-btns"><button class="btn primary" data-act="tr-skip">Next</button><button class="btn" data-act="speak" data-t="${esc(g.p.gr)}">🔊</button>${!ok ? `<button class="btn" data-act="ai-check-tr">✨ Was mine OK?</button>` : ''}</div><div id="aiBox"></div>`;
    g.given = given; g.done = true;
  };
  A.acts['tr-skip'] = () => { game.done = true; A.routes.translate(); };
  A.acts['ai-check-tr'] = async function () {
    const box = A.$('#aiBox');
    if (!A.aiReady()) { box.innerHTML = A.needKeyCard(); return; }
    box.innerHTML = `<p class="muted thinking">Asking ${A.AI}…</p>`;
    try {
      const r = await A.ask({ system: window.AI.prompts.check, messages: [{ role: 'user', content: `Intended meaning (English): "${game.p.en}"\nA model answer: "${game.p.gr}"\nMy ${A.LANG.name}: "${game.given}"\nIs mine correct and natural? Correct it.` }], maxTokens: 1500 });
      box.innerHTML = renderCheck(window.AI.parseJSON(r));
    } catch (e) { box.innerHTML = `<p class="muted">${esc(e.message)}</p>`; }
  };

  A.routes.dictation = function () {
    if (!game || game.kind !== 'dictation' || game.done) { game = { kind: 'dictation', p: A.pick(A.stagePhrases().filter(p => p.gr.split(/\s+/).length >= 3)), done: false }; setTimeout(() => A.speak(game.p.gr, 0.85), 400); }
    const g = game;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Dictation</h1></header>
      <article class="card"><p class="cue">Listen and type what you hear</p>
        <div class="row-btns center"><button class="btn sun big" data-act="dict-play">🔊 Play</button><button class="btn" data-act="dict-slow">🐢 Slowly</button></div>
        <form data-form="dictation"><textarea name="a" rows="2" lang="${A.LANG.code}" autocapitalize="off" spellcheck="false" placeholder="${esc(A.LANG.writePlaceholder)}"></textarea><div class="row-btns"><button class="btn primary" type="submit">Check</button><button type="button" class="btn ghost" data-act="dict-skip">Skip</button></div></form>
        <div class="answer" hidden></div></article>`;
  };
  A.acts['dict-play'] = () => A.speak(game.p.gr, 0.9);
  A.acts['dict-slow'] = () => A.speak(game.p.gr, 0.55);
  A.acts['dict-skip'] = () => { game.done = true; A.routes.dictation(); };
  A.forms.dictation = function (f, fd) {
    const given = (fd.get('a') || '').trim(), sim = A.similarity(given, game.p.gr), ok = sim >= 0.92;
    A.recordCat('dictation', ok); A.xp(ok ? 3 : 1); A.save();
    const a = A.$('.answer'); a.hidden = false;
    a.innerHTML = `<p class="verdict ${ok ? 'ok' : sim > 0.75 ? 'mid' : 'bad'}">${ok ? 'Perfect' : Math.round(sim * 100) + '% match'}</p><p class="card-ex" lang="${A.LANG.code}">${A.diffWords(given, game.p.gr)}</p><p class="muted">${esc(game.p.en)}</p><div class="row-btns"><button class="btn primary" data-act="dict-skip">Next</button></div>`;
    game.done = true;
  };

  // ---------------- CLAUDE TEST ----------------
  A.routes.aitest = async function () {
    if (!A.aiReady()) { A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>${A.AI} test</h1><p class="muted">${A.AI} writes a fresh 8-question test from your own words, mixing vocabulary, gender, cases and verb forms.</p></header>${A.needKeyCard()}`; return; }
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>${A.AI} test</h1></header><section class="done-card"><div class="spinner"></div><p class="muted">Writing a test from your words…</p></section>`;
    const src = A.db.words.length >= 6 ? A.shuffle(A.db.words.slice()).slice(0, 25).map(w => A.plainHead(w) + ' = ' + w.meaning) : A.wordsOfDay().concat(A.shuffle(A.stageDict().slice()).slice(0, 20)).map(e => A.entryHead(e) + ' = ' + e.meaning);
