  // ---------------- GRAMMAR ----------------
  A.routes.grammar = function () {
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Grammar</h1><p class="muted">Short explanations with a quiz after each one.</p></header>
      ${lessonGroups()}`;
  };
  function lessonRow(l) { const r = A.db.lessons[l.id]; const tag = A.stageInfo ? (A.LANG.stages.find(x => x.id === l.level) || {}).name || '' : ['', 'B1', 'B2', 'C1'][l.level]; return `<li><a class="lesson-row ${A.unlocked(l.level) ? '' : 'later'}" href="#/lesson/${l.id}"><span class="lv lv${Math.min(3, l.level)}">${esc(tag)}</span>`;}
  function lessonGroups() {
    const now = A.grammar.filter(l => A.unlocked(l.level)), later = A.grammar.filter(l => !A.unlocked(l.level));
    const list = ls => `<ul class="list lessons">${ls.map(l => { const r = A.db.lessons[l.id]; return lessonRow(l) + `<span class="ls-text"><strong>${esc(l.title)}</strong><small>${esc(l.summary)}</small></span>${r ? `<span class="ls-score ${r.best / r.total >= 0.8 ? 'ok' : ''}">${r.best}/${r.total}</span>` : ''}</a></li>`; }).join('')}</ul>`;
    return list(now) + (later.length ? `<h2>Coming later</h2><p class="tiny">For higher levels. You can still open them.</p>` + list(later) : '');
  }
  A.routes.lesson = function (id) {
    const l = A.grammar.find(x => x.id === id); if (!l) return A.go('#/grammar');
    const body = l.body.split('\n').map(line => {
      if (line.startsWith('- ')) return `<li>${fmt(line.slice(2))}</li>`;
      if (line.startsWith('> ')) { const [gr, en] = line.slice(2).split(' | '); return `<div class="ex-line"><span lang="${A.LANG.code}">${A.tappable(gr)}</span>${en ? `<small>${esc(en)}</small>` : ''}</div>`; }
      if (line.startsWith('! ')) return `<p class="tipline">${fmt(line.slice(2))}</p>`;
      if (line.startsWith('## ')) return `<h3 class="ls-h">${esc(line.slice(3))}</h3>`;
      if (line.startsWith('| ')) return `<tr>${line.replace(/^\|\s*|\s*\|\s*$/g, '').split(/\s*\|\s*/).map(c => `<td lang="${A.LANG.code}"${c.length <= 18 ? ' class="nw"' : ''}>${fmt(c)}</td>`).join('')}</tr>`;
      return line.trim() ? `<p>${fmt(line)}</p>` : '';
    }).join('').replace(/(<li>.*?<\/li>)+/g, m => `<ul class="bul">${m}</ul>`)
      .replace(/(<tr>.*?<\/tr>)+/g, m => `<div class="tbl-wrap"><table class="ls-table">${m.replace(/<tr>(.*?)<\/tr>/, (x, r) => `<tr class="th">${r}</tr>`)}</table></div>`);
    const course = l.course ? A.grammar.filter(x => x.course === l.course) : [], next = course[course.indexOf(l) + 1];
    A.view().innerHTML = `<header class="top"><a class="back" href="#/grammar">Grammar</a><h1>${esc(l.title)}</h1></header>
      <article class="lesson">${body}</article>
      <button class="btn primary wide big" data-act="lesson-quiz" data-id="${l.id}">Take the quiz (${l.quiz.length})</button>
      ${l.course === 'cases' ? `<div class="row-btns">${next ? `<a class="btn" href="#/lesson/${next.id}">Next: ${esc(next.title.replace(/^Cases \d+: /, ''))} →</a>` : ''}<a class="btn" href="#/cases">Cases trainer</a></div>` : ''}`;
  };
  const fmt = s => A.tappable(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  A.acts['lesson-quiz'] = function (el) {
    const l = A.grammar.find(x => x.id === el.dataset.id);
    const run = () => A.runQuiz({ title: l.title, questions: A.shuffle(l.quiz.map(q => ({ q: q.q, o: q.o, a: q.a, ex: q.ex, cat: 'grammar' }))).map(shuffleOpts), back: '#/lesson/' + l.id, backLabel: 'Lesson', retry: run,
      onDone: (r, t) => { const prev = A.db.lessons[l.id]; A.db.lessons[l.id] = { best: Math.max(r, prev ? prev.best : 0), total: t, last: Date.now() }; } });
    run();
  };
  function shuffleOpts(q) { const idx = A.shuffle(q.o.map((_, i) => i)); return Object.assign({}, q, { o: idx.map(i => q.o[i]), a: idx.indexOf(q.a) }); }

  // ---------------- PHRASES ----------------
  let phraseTopic = null;
  A.routes.phrases = function (topic) {
    const topics = Array.from(new Set((A._allPhrases ? A.phrases : A.stagePhrases()).map(p => p.topic)));
    const moreBtn = A.stagePhrases().length < A.phrases.length ? `<button class="chip" data-act="ph-more">${A._allPhrases ? '− Fewer topics' : '＋ Harder topics'}</button>` : '';
    phraseTopic = topic || (topics.includes(phraseTopic) ? phraseTopic : null) || topics[0];
    const list = A.phrases.filter(p => p.topic === phraseTopic);
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Everyday ${A.LANG.name}</h1></header>
      <div class="chips">${topics.map(t => `<button class="chip ${t === phraseTopic ? 'on' : ''}" data-act="ph-topic" data-t="${esc(t)}">${esc(t)}</button>`).join('')}${moreBtn}</div>
      <ul class="list phrases">${list.map((p, i) => `<li class="phrase"><div class="ph-text"><p class="ph-gr" lang="${A.LANG.code}">${A.tappable(p.gr)}</p><p class="ph-en">${esc(p.en)}</p></div>
        <div class="ph-btns"><button class="icon-btn" data-act="speak" data-t="${esc(p.gr)}" aria-label="Listen">🔊</button><button class="icon-btn" data-act="ph-save" data-i="${A.phrases.indexOf(p)}" aria-label="Save to my words">${A.findByLemma(p.gr) ? '✓' : '+'}</button></div></li>`).join('')}</ul>
      <button class="btn primary wide" data-act="ph-practise">Practise this topic</button>`;
  };
  A.acts['ph-more'] = () => { A._allPhrases = !A._allPhrases; phraseTopic = null; A.routes.phrases(); };
  A.acts['ph-topic'] = el => { phraseTopic = el.dataset.t; A.routes.phrases(phraseTopic); };
  A.acts['ph-save'] = function (el) {
    const p = A.phrases[+el.dataset.i]; if (A.findByLemma(p.gr)) return A.toast('Already saved');
    A.db.words.push(A.newWord({ lemma: p.gr, pos: 'other', meaning: p.en, tags: ['phrase'], source: 'Everyday ' + A.LANG.name }));
    A.save(); A.resetIndex(); A.xp(1); el.textContent = '✓'; A.toast('Saved to your words');
  };
  A.acts['ph-practise'] = function () {
    const list = A.phrases.filter(p => p.topic === phraseTopic);
    const qs = A.shuffle(list.slice()).slice(0, 8).map(p => { const o = distract(p.gr, list.length >= 4 ? list : A.phrases, 'gr'); return { q: p.en, o, a: o.indexOf(p.gr), cat: 'phrase', ex: '' }; });
    A.runQuiz({ title: phraseTopic, questions: qs, back: '#/phrases', backLabel: 'Phrases', retry: () => A.acts['ph-practise']() });
  };

  // ---------------- READING ----------------
  A.routes.reading = function () {
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Reading</h1><p class="muted">Tap or long-press any word to see what it means and add it to your words. Questions at the end.</p></header>
      <ul class="list lessons">${A.readings.slice().sort((x, y) => (A.unlocked(y.stage) - A.unlocked(x.stage))).map(r => { const d = A.db.readings[r.id]; return `<li><a class="lesson-row ${A.unlocked(r.stage) ? '' : 'later'}" href="#/read/${r.id}"><span class="lv lv${r.level === 'B1' ? 1 : r.level === 'B2' ? 2 : 3}">${r.level}</span><span class="ls-text"><strong lang="${A.LANG.code}">${esc(r.title)}</strong><small>${esc(r.en)}</small></span>${d ? `<span class="ls-score ${d.best === r.q.length ? 'ok' : ''}">${d.best}/${r.q.length}</span>` : ''}</a></li>`; }).join('')}</ul>
      ${A.aiReady() ? `<button class="btn wide" data-act="ai-story">✨ Ask ${A.AI} for a new text</button>` : ''}`;
  };
  A.routes.read = function (id) {
    const r = A.readings.find(x => x.id === id) || (A._aiStory && A._aiStory.id === id ? A._aiStory : null);
    if (!r) return A.go('#/reading');
    A.view().innerHTML = `<header class="top"><a class="back" href="#/reading">Reading</a><p class="lv-line"><span class="lv">${esc(r.level)}</span> ${esc(r.en)}</p><h1 lang="${A.LANG.code}">${esc(r.title)}</h1></header>
      <div class="row-btns"><button class="btn sm" data-act="speak" data-t="${esc(r.text)}">🔊 Read aloud</button><button class="btn sm ghost" data-act="read-size">Aa</button></div>
      <article class="reading" lang="${A.LANG.code}">${r.text.split(/\n+/).map(par => `<p>${A.tappable(par).replace(/<button class="tw" data-act="lookup" data-t="([^"]+)">/g, (m, t) => `<button class="tw" data-act="lookup" data-t="${t}" data-ctx="${esc(sentenceOf(r.text, t))}">`)}</p>`).join('')}</article>
      ${r.q && r.q.length ? `<button class="btn primary wide big" data-act="read-quiz" data-id="${esc(r.id)}">Answer ${r.q.length} questions</button>` : ''}`;
  };
  const sentenceOf = (text, w) => (text.split(/(?<=[.;!?·])\s+/).find(s => s.includes(w)) || '').slice(0, 220);
  A.acts['read-size'] = () => { document.body.classList.toggle('big-read'); };
  A.acts['read-quiz'] = function (el) {
    const r = A.readings.find(x => x.id === el.dataset.id) || A._aiStory;
    const run = () => A.runQuiz({ title: r.title, questions: r.q.map(q => shuffleOpts({ q: q.q, o: q.o, a: q.a, cat: 'reading' })), back: '#/read/' + r.id, backLabel: 'Text', retry: run,
      onDone: (s) => { const p = A.db.readings[r.id]; A.db.readings[r.id] = { best: Math.max(s, p ? p.best : 0), last: Date.now() }; } });
    run();
  };
  A.acts['ai-story'] = async function () {
    A.view().innerHTML = `<header class="top"><a class="back" href="#/reading">Reading</a><h1>New text</h1></header><section class="done-card"><div class="spinner"></div><p class="muted">${A.AI} is writing a text with some of your words…</p></section>`;
    const words = A.shuffle(A.db.words.slice()).slice(0, 8).map(w => w.lemma).join(', ');
    try {
