  };

  // ---------------- WRITING ----------------
  const PROMPTS = A.LANG.writingPrompts || [];
  A.routes.writing = function () {
    const p = PROMPTS[A.dayIndex() % PROMPTS.length];
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Writing</h1></header>
      <div class="tile-grid">
        <a href="#/translate" class="tile"><span class="glyph">🔁</span><strong>Translate</strong><small>English → Greek sentences</small></a>
        <a href="#/scramble" class="tile"><span class="glyph">⇄</span><strong>Word order</strong><small>Build the sentence</small></a>
        <a href="#/dictation" class="tile"><span class="glyph">🎧</span><strong>Dictation</strong><small>Listen and write</small></a>
      </div>
      <section class="write-box"><h2>Free writing</h2><p class="prompt-line" id="wprompt">${esc(p)}</p><button class="linkish" data-act="w-new">Another prompt</button>
        <form data-form="freewrite"><textarea name="t" rows="7" lang="${A.LANG.code}" placeholder="${esc(A.LANG.writePlaceholder)}">${esc(A.db.draftText || '')}</textarea>
        <div class="row-btns"><button class="btn primary" type="submit">✨ Check with ${A.AI}</button><span class="tiny" id="wc"></span></div></form>
        <div id="fwResult"></div></section>`;
  };
  A.acts['w-new'] = () => { A.$('#wprompt').textContent = A.pick(PROMPTS); };
  A.forms.freewrite = async function (f, fd) {
    const t = (fd.get('t') || '').trim(); if (!t) return;
    A.db.draftText = t; A.save();
    const box = A.$('#fwResult');
    if (!A.aiReady()) { box.innerHTML = A.needKeyCard(); return; }
    box.innerHTML = `<p class="muted thinking">${A.AI} is reading your text…</p>`;
    try {
      const r = await A.ask({ system: window.AI.prompts.check, messages: [{ role: 'user', content: `Prompt: ${A.$('#wprompt').textContent}\n\nMy text:\n${t}` }], maxTokens: 2500 });
      box.innerHTML = renderCheck(window.AI.parseJSON(r)); A.xp(5); A.recordCat('writing', true); A.save();
    } catch (e) { box.innerHTML = `<p class="muted">${esc(e.message)}</p>`; }
  };
  function renderCheck(d) {
    return `<div class="check">${d.comment ? `<p class="check-comment">${esc(d.comment)}</p>` : ''}
      ${d.mistakes && d.mistakes.length ? `<ul class="mistakes">${d.mistakes.map(m => `<li><span class="wrong" lang="${A.LANG.code}">${esc(m.wrong)}</span> → <span class="right" lang="${A.LANG.code}">${esc(m.right)}</span><small>${esc(m.why)}</small></li>`).join('')}</ul>` : '<p class="verdict ok">No mistakes found. Μπράβο!</p>'}
      ${d.corrected ? `<p class="label">Corrected</p><p class="card-ex" lang="${A.LANG.code}">${A.tappable(d.corrected)}</p>` : ''}
      ${d.better ? `<p class="label">More natural</p><p class="card-ex" lang="${A.LANG.code}">${A.tappable(d.better)}</p>` : ''}</div>`;
  }

  // ---------------- TUTOR ----------------
  const TOPICS = A.LANG.tutorTopics || [];
  A.routes.tutor = function () {
    if (!A.aiReady()) { A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Talk with ${A.AI}</h1><p class="muted">Chat in ${A.LANG.name} about anything. ${A.AI} keeps it at your level, asks you questions, and corrects your mistakes after each message. Tap any word in its replies to look it up.</p></header>${A.needKeyCard()}`; return; }
    const chat = A.db.chat;
    A.view().innerHTML = `<div class="chat-wrap">
      <header class="top chat-top"><a class="back" href="#/learn">Learn</a><div class="chat-head"><h1>Talk with ${A.AI}</h1><button class="btn sm ghost" data-act="chat-new">New chat</button></div>
        <div class="chips">${TOPICS.map(t => `<button class="chip ${A.db.chatTopic === t ? 'on' : ''}" data-act="chat-topic" data-t="${esc(t)}">${esc(t)}</button>`).join('')}</div></header>
      <div class="chat" id="chat">${chat.filter(m => !m.hidden).length ? chat.filter(m => !m.hidden).map(renderMsg).join('') : `<div class="chat-empty"><p>${esc(A.LANG.chatHello)}</p></div>`}</div>
      <form data-form="chat" class="chat-input">${A.canListen() ? '<button type="button" class="btn mic-chat" data-act="mic-fill" aria-label="Speak">🎙️</button>' : ''}<textarea name="m" rows="1" lang="${A.LANG.code}" placeholder="${esc(A.LANG.chatPlaceholder)}" autocapitalize="sentences"></textarea><button class="btn primary" type="submit" aria-label="Send">➤</button></form></div>`;
    const c = A.$('#chat'); c.scrollTop = c.scrollHeight; window.scrollTo(0, document.body.scrollHeight);
  };
  function renderMsg(m) {
    if (m.role === 'user') return `<div class="msg me" lang="${A.LANG.code}">${esc(m.content)}</div>`;
    const [main, ...corr] = m.content.split(/\n(?=✏️)/);
    return `<div class="msg ai"><p lang="${A.LANG.code}">${A.tappable(main.trim()).replace(/\n/g, '<br>')}</p>${corr.length ? `<div class="corr">${esc(corr.join('\n')).replace(/\n/g, '<br>')}</div>` : ''}<button class="icon-btn sm" data-act="speak" data-t="${esc(main.trim())}" aria-label="Listen">🔊</button></div>`;
  }
  A.acts['chat-new'] = () => { A.db.chat = []; A.save(); A.routes.tutor(); };
  A.acts['chat-topic'] = el => { A.db.chatTopic = el.dataset.t; A.db.chat = []; A.save(); A.routes.tutor(); sendChat(A.LANG.topicStart(el.dataset.t), true); };
  A.forms.chat = (f, fd) => { const m = (fd.get('m') || '').trim(); if (m) sendChat(m); };
  async function sendChat(text, hidden) {
    const chat = A.db.chat;
    chat.push({ role: 'user', content: text, hidden: !!hidden });
    const box = A.$('#chat');
    if (!hidden) box.insertAdjacentHTML('beforeend', renderMsg({ role: 'user', content: text }));
    box.insertAdjacentHTML('beforeend', '<div class="msg ai typing"><span></span><span></span><span></span></div>');
    const ta = A.$('.chat-input textarea'); if (ta) ta.value = '';
    box.scrollTop = box.scrollHeight; window.scrollTo(0, document.body.scrollHeight);
    try {
      const msgs = chat.slice(-20).map(m => ({ role: m.role, content: m.content }));
      while (msgs.length && msgs[0].role !== 'user') msgs.shift();
      const reply = await A.ask({ system: window.AI.prompts.tutor(A.db.chatTopic), messages: msgs, maxTokens: 700 });
      chat.push({ role: 'assistant', content: reply });
      if (chat.length > 60) chat.splice(0, chat.length - 60);
      A.xp(2); A.save();
    } catch (e) { chat.pop(); A.save(); A.toast(e.message); }
    if ((location.hash || '') === '#/tutor') A.routes.tutor();
  }

