      <div class="chips wrap">${['Cooking verbs', 'Office life', 'Instagram slang', 'Emotions', 'The beach', 'Doctor visit', 'Politics', 'Arguments'].map(t => `<button class="chip" data-act="suggest-chip" data-t="${t}">${t}</button>`).join('')}</div>
      <div id="sugg"></div>` : A.needKeyCard()}`;
  };
  A.acts['suggest-chip'] = el => { A.$('form[data-form="suggest"] input').value = el.dataset.t; A.forms.suggest(null, new Map([['t', el.dataset.t]])); };
  A.forms.suggest = async function (f, fd) {
    const t = (fd.get('t') || '').trim(); if (!t) return;
    const box = A.$('#sugg'); box.innerHTML = '<p class="muted thinking">Thinking of words…</p>';
    try {
      const have = A.db.words.slice(-80).map(w => w.lemma).join(', ');
      const r = await A.ask({ system: window.AI.prompts.suggest, messages: [{ role: 'user', content: `Topic: ${t}\nGive 10 words. Avoid words I already have: ${have}` }], maxTokens: 3500 });
      A._sugg = window.AI.parseJSON(r);
      box.innerHTML = `<ul class="list words">${A._sugg.map((d, i) => { const g = G.ART_TO_G[d.article] || ''; return `<li><div class="word-row dict g-bar-${g || 'x'}"><div class="dr-main"><span class="wr-head">${g ? `<span class="art g-${g}">${esc(d.article)}</span> ` : ''}<span class="lemma">${esc(d.lemma)}</span></span><span class="wr-mean">${esc(d.meaning)}</span>${d.example ? `<span class="tiny" lang="${A.LANG.code}">${esc(d.example)}</span>` : ''}</div><button class="dr-add" data-act="sugg-add" data-i="${i}">+</button></div></li>`; }).join('')}</ul>`;
    } catch (e) { box.innerHTML = `<p class="muted">${esc(e.message)}</p>`; }
  };
  A.acts['sugg-add'] = el => { const w = A.addAiWord(A._sugg[+el.dataset.i], A.AI + ' suggestion'); if (w) { el.textContent = '✓'; el.classList.add('on'); } };

  // ---------------- PROGRESS ----------------
  A.routes.progress = function () {
    const db = A.db; let cards = 0, mature = 0, dueTomorrow = 0; const tmr = A.today() + 2 * A.DAY;
    db.words.forEach(w => Object.values(w.srs).forEach(s => { cards++; if (s.ivl >= 21) mature++; if (s.due < tmr) dueTomorrow++; }));
    const days = []; for (let i = 13; i >= 0; i--) { const k = A.dayKey(A.today() - i * A.DAY); days.push({ k, n: (db.stats.days[k] || {}).xp || 0, d: new Date(A.today() - i * A.DAY) }); }
    const mx = Math.max(db.settings.goal, ...days.map(d => d.n));
    const cats = Object.entries(db.stats.cats).map(([cat, v]) => ({ cat, acc: v.c / v.n, n: v.n })).sort((a, b) => a.acc - b.acc);
    const li = A.levelInfo();
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Progress</h1></header>
      <a class="level-card" href="#/badges"><div class="lv-big">${li.level}</div><div class="lv-info"><strong>Level ${li.level}</strong><span class="xp-bar"><i style="width:${Math.round(li.into / li.span * 100)}%"></i></span><small>${li.into} / ${li.span} XP to level ${li.level + 1}</small></div></a>
      <section class="kpis"><div><b>${db.words.length}</b><span>words</span></div><div><b>${mature}</b><span>well known</span></div><div><b>${A.streak()}</b><span>day streak</span></div><div><b>${db.stats.best.flash || 0}</b><span>best flash</span></div></section>
      <section><h2>Points, last 14 days</h2><div class="bars" role="img" aria-label="Points per day">${days.map(d => `<span class="bar-col"><span class="bar ${d.n >= db.settings.goal ? 'goal' : d.n ? '' : 'zero'}" style="height:${Math.max(3, d.n / mx * 100)}%"></span><small>${'SMTWTFS'[d.d.getDay()]}</small></span>`).join('')}<i class="goal-line" style="bottom:${db.settings.goal / mx * 100}%"></i></div>
        <p class="tiny">${dueTomorrow} cards due by tomorrow · ${cards} cards started · goal ${db.settings.goal} points a day</p></section>
      <section><h2>Accuracy by area</h2>${cats.length ? `<ul class="acc">${cats.map(c => `<li><span>${esc(A.CAT_LABEL[c.cat] || c.cat)}</span><span class="acc-bar"><i style="width:${Math.round(c.acc * 100)}%" class="${c.acc < 0.6 ? 'low' : c.acc < 0.8 ? 'mid' : 'ok'}"></i></span><b>${Math.round(c.acc * 100)}%</b></li>`).join('')}</ul>` : `<p class="muted">Practise a little to see where you're strong and weak.</p>`}</section>`;
  };

  // ---------------- SETTINGS & BACKUP ----------------
  A.routes.settings = function () {
    const s = A.db.settings, gl = A.global;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Settings</h1></header>
      <section><h2>Language</h2><p class="tiny">Each language keeps its own words and progress. Your AI key is shared.</p>
        <div class="lang-list">${(window.LEXEIS_LANGS || []).map(l => `<button class="lang-card ${l.code === A.LANG.code ? 'on' : ''}" data-act="set-lang" data-l="${l.code}"><span class="lc-flag">${l.flag}</span><span class="lc-text"><strong>${l.name} · ${l.native}</strong><small>${l.level}</small></span>${l.code === A.LANG.code ? '<span class="lc-on">✓</span>' : ''}</button>`).join('')}</div></section>
      ${A.LANG.stages ? `<section><h2>${esc(A.LANG.name)} level</h2><p class="tiny">Sets which words, tenses, lessons and texts you practise. Move up whenever it feels easy; your words stay.</p>
        <div class="lang-list">${A.LANG.stages.map(st => `<button class="lang-card ${A.stageInfo && st.id === A.stageInfo.id ? 'on' : ''}" data-act="set-stage" data-s="${st.id}"><span class="lc-flag stage-num">${st.id}</span><span class="lc-text"><strong>${esc(st.name)}</strong><small>${esc(st.desc)}</small></span>${A.stageInfo && st.id === A.stageInfo.id ? '<span class="lc-on">✓</span>' : ''}</button>`).join('')}</div></section>` : ''}
      <section><h2>Reminders and sound</h2>
        <label class="toggle"><input type="checkbox" data-change="rem-on" ${A.remSettings().reminders ? 'checked' : ''}> Daily reminder</label>
        <label class="field inline"><span>Reminder time</span><input type="time" value="${A.remSettings().time}" data-change="rem-time"></label>
        <label class="toggle"><input type="checkbox" data-change="rem-streak" ${A.remSettings().streakSaver ? 'checked' : ''}> Streak saver at 8:45pm if you haven't practised</label>
        <label class="toggle"><input type="checkbox" data-change="sound" ${A.global.sound === false ? '' : 'checked'}> Sound effects</label>
        <div class="row-btns"><button class="btn sm" data-act="rem-test">Send a test reminder</button></div></section>
      <section><h2>App updates</h2><p class="tiny">Version ${esc(window.APP_VERSION || '')} (build ${window.APP_BUILD || 'dev'}). New versions download automatically when you open the app.</p>
        <p class="tiny" id="updStatus">${esc(A.updateStatus ? A.updateStatus() : '')}</p>
        <div class="row-btns"><button class="btn" data-act="check-updates">Check for updates</button><button class="btn ghost" data-act="open-url" data-url="${esc(A.APK_URL)}">Download latest APK</button></div></section>
      <section><h2>AI features</h2><p class="tiny">${A.AI}'s smart features (Ask, the tutor, tests, word ideas) run on Claude, made by Anthropic, using your own key. The key is stored only on this phone and sent only to Anthropic. Create one at console.anthropic.com → API keys, and add credit under Billing.</p>
        <label class="field"><span>API key</span><input type="password" value="${esc(gl.apiKey)}" data-input="apiKey" placeholder="sk-ant-…" autocomplete="off" autocapitalize="off" spellcheck="false"></label>
        <label class="field"><span>Model</span><select data-change="model">${window.AI.MODELS.map(m => `<option value="${m.id}" ${gl.model === m.id ? 'selected' : ''}>${esc(m.label)}</option>`).join('')}</select></label>
        <div class="row-btns"><button class="btn" data-act="ai-test">Test connection</button><button class="btn ghost" data-act="open-url" data-url="https://console.anthropic.com/settings/keys">Get a key</button></div><p class="tiny" id="aiStatus"></p></section>
      <section><h2>Daily routine</h2>
        <label class="field inline"><span>Daily goal (points)</span><input type="number" min="5" max="500" value="${s.goal}" data-input="goal"></label>
        <label class="field inline"><span>New cards per day</span><input type="number" min="0" max="100" value="${s.newPerDay}" data-input="newPerDay"></label>
        <p class="tiny">Points: 2 per review, 1–3 per drill answer, 5 for checked writing. 30 a day is about 10 minutes.</p></section>
      <section><h2>Share</h2><div class="row-btns"><a class="btn" href="#/shareapp">📲 Share the app</a></div></section>
      <section><h2>Data</h2><div class="row-btns"><a class="btn" href="#/backup">Backup and export</a></div></section>
      <p class="tiny center">Λέξεις · ${A.LANG.name} · ${A.dict.length} dictionary words</p>`;
  };
  A.inputs.apiKey = v => { A.global.apiKey = v.trim(); A.saveGlobal(); };
  A.inputs.goal = v => { A.db.settings.goal = Math.max(5, Math.min(500, +v || 30)); A.save(); };
  A.inputs.newPerDay = v => { A.db.settings.newPerDay = Math.max(0, Math.min(100, +v || 0)); A.save(); };
  A.changes.model = el => { A.global.model = el.value; A.saveGlobal(); };
  A.acts['ai-test'] = async function () {
    const st = A.$('#aiStatus'); st.textContent = 'Testing…';
    try { const r = await A.ask({ system: `Reply with one short ${A.LANG.name} greeting.`, messages: [{ role: 'user', content: 'Hello!' }], maxTokens: 40 }); st.textContent = '✓ Connected. ' + A.AI + ' says: ' + r; }
    catch (e) { st.textContent = '✕ ' + (e.message === 'NO_KEY' ? 'Paste your key first.' : e.message); }
  };
  A.routes.backup = function () {
    const db = A.db, safe = Object.assign({}, db, { settings: Object.assign({}, db.settings, { apiKey: '' }) });
    const json = JSON.stringify(safe);
    const csv = db.words.map(w => [A.plainHead(w), w.meaning, (w.examples[0] || {}).text || '', (w.tags || []).join(' ')].map(x => '"' + String(x).replace(/"/g, '""') + '"').join(',')).join('\n');
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Backup and export</h1><p class="muted">Your words live on this phone. Copy a backup now and then and keep it somewhere safe, such as a note or an email to yourself. (Your API key is left out.)</p></header>
      <section><h2>Full backup (all languages)</h2><p class="tiny">Everything: Greek, Spanish and French words and progress. Use this before reinstalling the app.</p><div class="row-btns"><button class="btn primary" data-act="copy" data-what="full">Copy full backup</button></div></section>
      <section><h2>Backup of ${esc(A.LANG.name)} only</h2><textarea class="code" readonly rows="3">${esc(json)}</textarea><div class="row-btns"><button class="btn" data-act="copy" data-what="json">Copy ${esc(A.LANG.name)} backup</button></div></section>
      <section><h2>Restore</h2><textarea class="code" rows="4" id="restore" placeholder="Paste a backup here"></textarea><div class="row-btns"><button class="btn" data-act="restore" data-mode="merge">Add to my words</button><button class="btn danger" data-act="restore" data-mode="replace">Replace everything</button></div></section>
      <section><h2>Export for Anki</h2><p class="tiny">CSV: ${A.LANG.name}, meaning, example, tags.</p><div class="row-btns"><button class="btn" data-act="copy" data-what="csv">Copy CSV</button></div></section>
      <section><h2>Start over</h2><button class="btn danger ghost" data-act="wipe">Delete all words and progress</button></section>`;
    const full = { lexeisFull: 1, data: {} };
    for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (/^lexeis\.v1/.test(k)) full.data[k] = localStorage.getItem(k); }
    A._export = { json, csv, full: JSON.stringify(full) };
  };
  A.acts.copy = function (el) {
    const txt = A._export[el.dataset.what];
    (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(() => A.toast('Copied'), () => { const ta = A.$('textarea.code'); ta.value = txt; ta.select(); try { document.execCommand('copy'); A.toast('Copied'); } catch (e) { A.toast('Select the text and copy it'); } });
  };
  A.acts.restore = function (el) {
    let data; try { data = JSON.parse(A.$('#restore').value); } catch (e) { return A.toast('That is not a valid backup'); }
    if (data && data.lexeisFull && data.data) {
      Object.entries(data.data).forEach(([k, v]) => { if (/^lexeis\.v1/.test(k)) localStorage.setItem(k, v); });
      A.load(); A.resetIndex(); A.toast('Full backup restored for all languages'); return A.go('#/today');
    }
    if (!data || !Array.isArray(data.words)) return A.toast('That is not a valid backup');
    if (el.dataset.mode === 'replace') { localStorage.setItem(A.KEY, JSON.stringify(data)); A.load(); }
    else data.words.forEach(w => { if (!A.db.words.some(x => x.id === w.id)) A.db.words.push(w); });
    A.save(); A.resetIndex(); A.toast('Backup restored'); A.go('#/words');
  };
  A.acts.wipe = () => A.sheet(`<h2>Delete everything?</h2><p class="muted">All ${A.db.words.length} words and your progress will be removed from this phone. Copy a backup first if you might want them.</p><div class="row-btns"><button class="btn danger" data-act="wipe-yes">Delete everything</button><button class="btn ghost" data-act="sheet-close">Cancel</button></div>`);
  A.acts['wipe-yes'] = () => { localStorage.removeItem(A.KEY); A.load(); A.save(); A.resetIndex(); A.closeSheet(); A.toast('All data deleted'); A.go('#/today'); };

  // ---------------- SHARE THE APP ----------------
  const shareText = () => `Here's Λέξεις, our language app for Greek, Spanish and French 🐙\n\nDownload it here: ${A.APK_URL}\n\nOpen the downloaded file to install. If Android asks, allow installs from your browser or files app. After that it updates itself.`;
  A.routes.shareapp = function () {
    const t = encodeURIComponent(shareText());
    A.view().innerHTML = `<header class="top"><a class="back" href="#/learn">Learn</a><h1>Share the app</h1><p class="muted">Send Λέξεις to the family. It works for Greek, Spanish and French, and each person picks their language when they first open it.</p></header>
      <section class="share-qr"><img src="share-qr.svg" alt="QR code for the download link" onerror="this.parentNode.classList.add('noqr')"><p class="tiny">Scan with the other phone's camera to download.</p></section>
      <div class="share-grid">
        <button class="share-btn wa" data-act="open-url" data-url="https://wa.me/?text=${t}"><span>💬</span>WhatsApp</button>
        <button class="share-btn sms" data-act="open-url" data-url="sms:?body=${t}"><span>✉️</span>Text message</button>
        <button class="share-btn mail" data-act="open-url" data-url="mailto:?subject=${encodeURIComponent('Λέξεις: our language app')}&body=${t}"><span>📧</span>Email</button>
        <button class="share-btn copy" data-act="copy-link"><span>🔗</span>Copy link</button>
      </div>
      <section class="callout"><p><strong>Installing on their phone</strong></p><ol class="steps"><li>Open the link and download <b>Lexeis.apk</b>.</li><li>Tap the file to install. If Android blocks it, tap <b>Settings</b> and allow this source; on Samsung, turn off <b>Auto Blocker</b> first.</li><li>Open Λέξεις and pick a language. After that it updates itself.</li></ol></section>
      <p class="tiny center" style="word-break:break-all">${esc(A.APK_URL)}</p>`;
  };
  A.navFor.shareapp = 'learn';
  A.acts['copy-link'] = () => {
    const txt = shareText();
    (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(() => A.toast('Link and instructions copied'), () => {
      const ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); A.toast('Link and instructions copied'); } catch (e) { A.toast('Copy failed'); } ta.remove();
    });
  };

  // ---------------- BOOT & EVENTS ----------------
  // long-press any Greek word anywhere (reading texts, quiz questions, answers, examples) to look it up
  (function () {
    let timer = null, start = null, fired = false;
    const wordAt = (x, y) => {
      let node, off;
      if (document.caretRangeFromPoint) { const r = document.caretRangeFromPoint(x, y); if (!r) return null; node = r.startContainer; off = r.startOffset; }
      else if (document.caretPositionFromPoint) { const p = document.caretPositionFromPoint(x, y); if (!p) return null; node = p.offsetNode; off = p.offset; }
      if (!node || node.nodeType !== 3) return null;
      const t = node.textContent, wr = new RegExp('^' + A.LANG.wordRe.source + '$'), isW = c => !!c && wr.test(c);
      let a = off, b = off;
      while (a > 0 && isW(t[a - 1])) a--;
      while (b < t.length && isW(t[b])) b++;
      if (a === b) return null;
      return { word: t.slice(a, b), host: node.parentElement };
    };
    const ctxOf = (host, w) => {
      const box = host.closest('.reading p, .quiz-q, .opt, .ex-line, .ex-text, .lesson p, .lesson li, .lesson td, .card, .sheet') || host;
      const text = box.textContent.replace(/\s+/g, ' ').trim();
      return (text.split(/(?<=[.;!?·])\s+/).find(s => s.includes(w)) || text).slice(0, 220);
    };
    document.addEventListener('pointerdown', e => {
      fired = false; clearTimeout(timer);
      if (e.target.closest('#sheet, input, textarea, .nav, .token')) return;
      start = { x: e.clientX, y: e.clientY };
      timer = setTimeout(() => {
        const hit = wordAt(start.x, start.y); if (!hit) return;
        fired = true;
        if (navigator.vibrate) try { navigator.vibrate(15); } catch (_) {}
        A.acts.lookup({ dataset: { t: hit.word, ctx: ctxOf(hit.host, hit.word) } });
      }, 480);
    });
    document.addEventListener('pointermove', e => { if (start && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 10) clearTimeout(timer); });
    ['pointerup', 'pointercancel'].forEach(t => document.addEventListener(t, () => clearTimeout(timer)));
    // the release after a long-press must not also tap the word / pick the quiz answer
    document.addEventListener('click', e => { if (fired) { fired = false; e.preventDefault(); e.stopImmediatePropagation(); } }, true);
    document.addEventListener('contextmenu', e => { if (e.target.closest('[lang]')) e.preventDefault(); });
  })();

  // a link to the page you're already on (e.g. "Lesson" from a quiz shown in place) doesn't fire hashchange: re-render it ourselves
  document.addEventListener('click', e => {
    const a = e.target.closest('a[href^="#"]');
    if (a && !e.defaultPrevented && a.getAttribute('href') === (location.hash || '#/')) { e.preventDefault(); A.render(); }
  });
  document.addEventListener('click', e => {
    const el = e.target.closest('[data-act]'); if (!el) return;
    const fn = A.acts[el.dataset.act]; if (!fn) return;
    if (el.tagName === 'A' && el.dataset.act !== 'flash-stop' && el.dataset.act !== 'art-stop' && el.dataset.act !== 'sheet-close-go') e.preventDefault();
    fn(el, e);
  });
  document.addEventListener('submit', e => { e.preventDefault(); const f = e.target, fn = A.forms[f.dataset.form]; if (fn) fn(f, new FormData(f)); });
  document.addEventListener('input', e => { const k = e.target.dataset.input; if (k && A.inputs[k]) A.inputs[k](e.target.value, e.target); if (e.target.matches('.chat-input textarea')) { e.target.style.height = 'auto'; e.target.style.height = Math.min(140, e.target.scrollHeight) + 'px'; } });
  document.addEventListener('change', e => { const k = e.target.dataset.change; if (k && A.changes[k]) A.changes[k](e.target); if (e.target.dataset.pp) A.changes.pp(e.target); });
  document.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey && e.target.matches('.chat-input textarea')) { e.preventDefault(); e.target.form.requestSubmit(); } });

  A.load();
  window.addEventListener('hashchange', A.render);
  if (window.__lexeisPending) { const t = window.__lexeisPending; window.__lexeisPending = null; window.__lexeisShare(t); } else A.render();
  // the app started fine: tell the loader to keep using this (possibly over-the-air) version
  setTimeout(() => { if (window.lexeisBooted && document.querySelector('#view').children.length) window.lexeisBooted(); }, 1500);
  window.__lexeis = A;
})();

