/* Greek Cases trainer: endless generated practice of articles + cases, from real dictionary nouns.
   Two kinds of question: "fill the gap" (pick article + noun form) and "which case is this?". Tracks accuracy per case. */
(function () {
  if (!window.LANG || LANG.code !== 'el') return;
  const A = window.App, G = window.Greek, esc = A.esc;

  // keep ν before vowels and κ π τ ξ ψ (and μπ ντ γκ τσ τζ); drop it before other consonants
  function nRule(art, word) {
    if (art !== 'την') return art;
    const w = G.strip(G.lower(word));
    return /^[αεηιουωκπτξψ]/.test(w) || /^(μπ|ντ|γκ|τσ|τζ)/.test(w) ? 'την' : 'τη';
  }
  const SE = { 'τον': 'στον', 'την': 'στην', 'τη': 'στη', 'το': 'στο', 'τους': 'στους', 'τις': 'στις', 'τα': 'στα' };

  // frames: case, number, Greek with ___, English with ~ for the noun, why (shown after answering)
  const FRAMES = [
    { c: 'nom', n: 'sg', gr: '___ είναι εδώ.', en: 'The ~ is here.', why: 'Subject of είναι.' },
    { c: 'nom', n: 'sg', gr: 'Πού είναι ___;', en: 'Where is the ~?', why: 'Subject: it comes after the verb, but it is still the subject.' },
    { c: 'nom', n: 'sg', gr: 'Μου αρέσει ___.', en: 'I like the ~.', why: 'With αρέσει the thing you like is the subject, so nominative.' },
    { c: 'nom', n: 'pl', gr: 'Πού είναι ___;', en: 'Where are the ~s?', why: 'Plural subject, after the verb.' },
    { c: 'nom', n: 'pl', gr: 'Μου αρέσουν ___.', en: 'I like the ~s.', why: 'With αρέσουν the things you like are the subject.' },
    { c: 'acc', n: 'sg', gr: 'Βλέπω ___.', en: 'I see the ~.', why: 'Direct object of βλέπω.' },
    { c: 'acc', n: 'sg', gr: 'Θέλω ___.', en: 'I want the ~.', why: 'Direct object of θέλω.' },
    { c: 'acc', n: 'sg', gr: 'Μιλάμε για ___.', en: 'We are talking about the ~.', why: 'για takes the accusative.' },
    { c: 'acc', n: 'sg', gr: 'Δεν μπορώ χωρίς ___.', en: "I can't manage without the ~.", why: 'χωρίς takes the accusative.' },
    { c: 'acc', n: 'sg', gr: 'Σκέφτομαι ___.', en: "I'm thinking about the ~.", why: 'Direct object of σκέφτομαι.' },
    { c: 'acc', n: 'sg', se: true, gr: 'Η φωτογραφία είναι κοντά ___.', en: 'The photo is near the ~.', why: 'κοντά σε + accusative; σε + article joins up (στον, στη(ν), στο).' },
    { c: 'acc', n: 'pl', gr: 'Βλέπεις ___;', en: 'Can you see the ~s?', why: 'Plural direct object.' },
    { c: 'acc', n: 'pl', gr: 'Ξέχασα ___.', en: 'I forgot the ~s.', why: 'Plural direct object.' },
    { c: 'acc', n: 'pl', gr: 'Ρώτησα για ___.', en: 'I asked about the ~s.', why: 'για + accusative.' },
    { c: 'acc', n: 'pl', se: true, gr: 'Έγραψα κάτι δίπλα ___.', en: 'I wrote something next to the ~s.', why: 'δίπλα σε + accusative; σε + τους/τις/τα = στους/στις/στα.' },
    { c: 'gen', n: 'sg', gr: 'Η φωτογραφία ___.', en: 'The photo of the ~.', why: '"of the ~" → genitive.' },
    { c: 'gen', n: 'sg', gr: 'Το χρώμα ___ μου αρέσει.', en: 'I like the colour of the ~.', why: '"of the ~" → genitive.' },
    { c: 'gen', n: 'sg', gr: 'Μιλήσαμε για την ιστορία ___.', en: 'We talked about the history of the ~.', why: '"of the ~" → genitive.' },
