    const s = spot, pct = s.total ? Math.round(s.right / s.total * 100) : 0;
    A.db.stats.best.casespot = Math.max(A.db.stats.best.casespot || 0, pct); A.save();
    const rows = ['nom', 'acc', 'gen', 'voc'].filter(c => s.per[c]).map(c => `<li><span>${G.CASE_LABEL[c]}</span><b class="${s.per[c].r === s.per[c].t ? 'ok' : ''}">${s.per[c].r} / ${s.per[c].t}</b></li>`).join('');
    const weak = ['nom', 'acc', 'gen', 'voc'].filter(c => s.per[c] && s.per[c].r < s.per[c].t).sort((a, b) => s.per[a].r / s.per[a].t - s.per[b].r / s.per[b].t)[0];
    A.view().innerHTML = `<header class="top"><a class="back" href="#/cases">Cases</a><h1>${s.right} / ${s.total}</h1></header>
      <section class="done-card">${A.ring(s.right, s.total || 1, 120, 'Score')}<p class="big-num">${pct}%</p>
        <ul class="cs-sum">${rows}</ul>
        <div class="row-btns"><button class="btn primary" data-act="cs-again" data-c="">Another 8 sentences</button>${weak ? `<button class="btn" data-act="cs-again" data-c="${weak}">Focus: ${G.CASE_LABEL[weak]}</button>` : ''}</div></section>`;
    spot = null;
  }
  A.acts['cs-again'] = el => { newSpot(el.dataset.c || ''); A.go('#/casespot'); };
  A.acts['cs-start'] = el => { newSpot(el.dataset.c || ''); A.go('#/casespot'); };

  A.routes.cases = function () {
    const s = stats(), wk = weakest();
    const bar = c => { const x = s[c] || { r: 0, t: 0 }, p = x.t ? Math.round(x.r / x.t * 100) : 0; return `<button class="case-bar" data-act="cases-go" data-c="${c}"><span class="cb-l">${G.CASE_LABEL[c]}</span><span class="cb-track"><span style="width:${p}%" class="${p >= 80 ? 'ok' : p >= 50 ? 'mid' : 'low'}"></span></span><span class="cb-n">${x.t ? p + '%' : '–'}</span></button>`; };
    const course = A.grammar.filter(l => l.course === 'cases'), done = course.filter(l => A.db.lessons[l.id]).length;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Cases trainer</h1><p class="muted">New sentences every round from real nouns: fill the gap with the right article and ending, or name the case.</p></header>
      <a class="feature t-sun" href="#/casespot" data-act="cs-start" data-c=""><span class="f-ico">🔎</span><span class="f-text"><strong>Case spotter</strong><small>Real Greek sentences. Name the case of every highlighted word, with the reason each time.</small></span></a>
      <button class="btn primary wide big" data-act="cases-go" data-c="">Mixed round (18)</button>
      ${wk ? `<button class="btn wide" data-act="cases-go" data-c="${wk}">Focus on your weakest: ${G.CASE_LABEL[wk]}</button>` : ''}
      <h2>Your accuracy</h2><p class="tiny">Tap a case to practise just that one.</p>
      <div class="case-bars">${['nom', 'acc', 'gen', 'voc'].map(bar).join('')}</div>
      <a class="feature t-sea" href="#/lesson/cases1"><span class="f-ico">📘</span><span class="f-text"><strong>Cases course</strong><small>${done}/${course.length} lessons done. Start with the big picture.</small></span></a>
      <button class="btn wide" data-act="cases-exam">Big test: all ${course.reduce((n, l) => n + l.quiz.length, 0)} course questions</button>`;
  };
  A.acts['cases-go'] = function (el) {
    const focus = el.dataset.c || '';
    const run = () => {
      const qs = build(focus);
      if (!qs.length) return A.toast('Not enough nouns at this level yet.');
      A.runQuiz({ title: focus ? G.CASE_LABEL[focus] + ' practice' : 'Cases trainer', questions: qs, back: '#/cases', backLabel: 'Cases', retry: run, cat: 'cases' });
    };
    run();
  };
  A.acts['cases-exam'] = function () {
    const course = A.grammar.filter(l => l.course === 'cases');
    const run = () => A.runQuiz({ title: 'Cases: big test', back: '#/cases', backLabel: 'Cases', retry: run, cat: 'grammar',
      questions: A.shuffle([].concat(...course.map(l => l.quiz))).map(q => { const idx = A.shuffle(q.o.map((_, i) => i)); return { q: q.q, o: idx.map(i => q.o[i]), a: idx.indexOf(q.a), ex: q.ex }; }),
      onDone: (r, t) => { A.db.stats.best.casesExam = Math.max(A.db.stats.best.casesExam || 0, r); } });
    run();
  };
})();

