/* Graded reading texts. Each has questions (o = options, a = correct index). */
window.LANG_READINGS = [
{ id: 'kid-hello', stage: 1, title: 'Γεια σου!', en: 'Hello!', level: 'A1', text: `Γεια σου! Με λένε Νίκο. Είμαι εννιά χρονών. Έχω μια αδερφή. Τη λένε Άννα. Έχουμε μια γάτα. Η γάτα είναι μικρή και άσπρη. Μου αρέσει το ποδόσφαιρο και το παγωτό!`,
  q: [{ q: 'Πόσο χρονών είναι ο Νίκος;', o: ['εννιά', 'δέκα', 'οχτώ'], a: 0 }, { q: 'Πώς λένε την αδερφή του;', o: ['Μαρία', 'Άννα', 'Ελένη'], a: 1 }, { q: 'Πώς είναι η γάτα;', o: ['μεγάλη και μαύρη', 'μικρή και άσπρη', 'μικρή και κόκκινη'], a: 1 }] },
{ id: 'kid-beach', stage: 1, title: 'Στην παραλία', en: 'At the beach', level: 'A1', text: `Είναι καλοκαίρι. Ο ήλιος είναι ζεστός. Η Μαρία και ο μπαμπάς είναι στην παραλία. Η Μαρία κολυμπάει στη θάλασσα. Ο μπαμπάς διαβάζει ένα βιβλίο. Μετά τρώνε καρπούζι. Μμμ, τι ωραίο!`,
  q: [{ q: 'Τι εποχή είναι;', o: ['χειμώνας', 'καλοκαίρι', 'άνοιξη'], a: 1 }, { q: 'Τι κάνει ο μπαμπάς;', o: ['κολυμπάει', 'διαβάζει', 'τρώει'], a: 1 }, { q: 'Τι τρώνε;', o: ['παγωτό', 'καρπούζι', 'πίτσα'], a: 1 }] },
{ id: 'kid-octopus', stage: 2, title: 'Το χταπόδι ο Όκτο', en: 'Okto the octopus', level: 'A1', text: `Ο Όκτο είναι ένα κόκκινο χταπόδι. Μένει στη θάλασσα, κοντά σε ένα μικρό νησί. Έχει οχτώ πόδια! Του αρέσει να παίζει με τα ψάρια και τα δελφίνια. Ένα πρωί βλέπει μια μπάλα στο νερό. «Τι είναι αυτό;» λέει. Παίρνει τη μπάλα και παίζει όλη μέρα. Είναι πολύ χαρούμενος!`,
  q: [{ q: 'Τι χρώμα είναι ο Όκτο;', o: ['μπλε', 'κόκκινο', 'πράσινο'], a: 1 }, { q: 'Πόσα πόδια έχει;', o: ['έξι', 'οχτώ', 'δέκα'], a: 1 }, { q: 'Τι βλέπει στο νερό;', o: ['ένα ψάρι', 'μια μπάλα', 'ένα βιβλίο'], a: 1 }] },
{ id: 'village', stage: 3, title: 'Καλοκαίρι στο χωριό', en: 'Summer in the village', level: 'B1',
  text: `Κάθε καλοκαίρι, όταν ήμουν παιδί, πηγαίναμε στο χωριό της γιαγιάς μου στην Πελοπόννησο. Το σπίτι ήταν μικρό, με μια μεγάλη αυλή γεμάτη λουλούδια και μια τεράστια συκιά. Το πρωί ξυπνούσαμε με τα κοκόρια και η γιαγιά μας έφτιαχνε τηγανίτες με μέλι. Τα μεσημέρια ήταν πολύ ζεστά, οπότε όλοι κοιμόντουσαν. Εμείς τα παιδιά όμως βγαίναμε κρυφά και παίζαμε στο ποτάμι. Το βράδυ όλο το χωριό μαζευόταν στην πλατεία. Οι μεγάλοι έπιναν τσίπουρο και συζητούσαν για πολιτική, ενώ εμείς τρέχαμε γύρω γύρω μέχρι αργά. Πέρσι γύρισα στο χωριό μετά από είκοσι χρόνια. Η συκιά είναι ακόμα εκεί.`,
  q: [
    { q: 'Πού ήταν το χωριό;', o: ['Στην Κρήτη', 'Στην Πελοπόννησο', 'Στη Θεσσαλονίκη'], a: 1 },
    { q: 'Τι έκαναν τα παιδιά τα μεσημέρια;', o: ['Κοιμόντουσαν', 'Έπαιζαν στο ποτάμι', 'Βοηθούσαν τη γιαγιά'], a: 1 },
    { q: 'Τι βρήκε ο αφηγητής όταν γύρισε;', o: ['Το σπίτι είχε πουληθεί', 'Η συκιά ήταν ακόμα εκεί', 'Η πλατεία ήταν άδεια'], a: 1 }
  ] },
{ id: 'coffee', stage: 3, title: 'Πάμε για καφέ;', en: 'Shall we go for a coffee?', level: 'B1',
  text: `Στην Ελλάδα το «πάμε για καφέ;» δεν σημαίνει απλώς ότι θα πιούμε έναν καφέ. Σημαίνει ότι θα καθίσουμε δύο ή τρεις ώρες, θα μιλήσουμε για όλα και θα κοιτάζουμε τον κόσμο που περνάει. Το καλοκαίρι ο πιο αγαπημένος καφές είναι ο φρέντο εσπρέσο, ένας κρύος καφές με πάγο. Οι μεγαλύτεροι προτιμούν τον ελληνικό καφέ, που φτιάχνεται στο μπρίκι και πίνεται σκέτος, μέτριος ή γλυκός. Αν ζητήσεις τον λογαριασμό μετά από είκοσι λεπτά, ο σερβιτόρος μπορεί να σε κοιτάξει με απορία. Ο καφές στην Ελλάδα δεν είναι ρόφημα, είναι κοινωνικός θεσμός.`,
  q: [
    { q: 'Πόση ώρα κρατάει συνήθως ένας καφές με φίλους;', o: ['Είκοσι λεπτά', 'Δύο ή τρεις ώρες', 'Όλη μέρα'], a: 1 },
    { q: 'Πώς φτιάχνεται ο ελληνικός καφές;', o: ['Με πάγο', 'Στο μπρίκι', 'Με γάλα'], a: 1 },
    { q: 'Τι λέει το κείμενο ότι είναι ο καφές;', o: ['Ένα ακριβό ποτό', 'Κοινωνικός θεσμός', 'Μια κακή συνήθεια'], a: 1 }
  ] },
{ id: 'nameday', stage: 3, title: 'Η γιορτή του Γιώργου', en: 'Giorgos\'s name day', level: 'B1',
  text: `Στις 23 Απριλίου ο Γιώργος γιορτάζει. Στην Ελλάδα η ονομαστική γιορτή είναι συχνά πιο σημαντική από τα γενέθλια. Από το πρωί το κινητό του δεν σταματάει: φίλοι, συγγενείς και συνάδελφοι τηλεφωνούν για να του ευχηθούν «Χρόνια πολλά!». Το βράδυ το σπίτι του είναι ανοιχτό. Κανείς δεν χρειάζεται πρόσκληση, όποιος θέλει έρχεται. Η γυναίκα του έχει ετοιμάσει πίτες, σουβλάκια και ένα μεγάλο ταψί γεμιστά. Οι καλεσμένοι φέρνουν γλυκά ή ένα μπουκάλι κρασί. Στο τέλος της βραδιάς ο Γιώργος είναι κουρασμένος αλλά ευτυχισμένος. Του χρόνου, πάλι!`,
  q: [
    { q: 'Πότε γιορτάζει ο Γιώργος;', o: ['Στις 23 Απριλίου', 'Στις 15 Αυγούστου', 'Την Πρωτοχρονιά'], a: 0 },
    { q: 'Χρειάζεται πρόσκληση για να πας στο σπίτι του;', o: ['Ναι', 'Όχι', 'Μόνο για τους συγγενείς'], a: 1 },
    { q: 'Τι φέρνουν οι καλεσμένοι;', o: ['Λουλούδια', 'Γλυκά ή κρασί', 'Τίποτα'], a: 1 }
  ] },
{ id: 'message', stage: 3, title: 'Μήνυμα από μια φίλη', en: 'A message from a friend', level: 'B1',
  text: `Έλα ρε, τι γίνεται; Χάθηκες! Σου έστειλα χθες αλλά δεν μου απάντησες, ελπίζω να είσαι καλά. Άκου, το Σάββατο κάνουμε ένα μικρό πάρτι στην ταράτσα για τα γενέθλια της Ελένης. Θα είμαστε καμιά δεκαριά άτομα, χαλαρά πράγματα, λίγο φαγητό, μουσική και πολλή πλάκα. Αν θέλεις, φέρε και τον αδερφό σου, τον έχουμε χρόνια να τον δούμε. Ξεκινάμε γύρω στις εννιά, αλλά έλα όποτε μπορείς. Α, και μην πεις τίποτα στην Ελένη, είναι έκπληξη! Πες μου μέχρι την Πέμπτη αν θα έρθεις. Φιλιά πολλά!`,
  q: [
    { q: 'Γιατί κάνουν πάρτι;', o: ['Για τη γιορτή της Ελένης', 'Για τα γενέθλια της Ελένης', 'Επειδή μετακόμισαν'], a: 1 },
    { q: 'Τι δεν πρέπει να κάνει ο φίλος;', o: ['Να αργήσει', 'Να πει κάτι στην Ελένη', 'Να φέρει τον αδερφό του'], a: 1 },
    { q: 'Μέχρι πότε πρέπει να απαντήσει;', o: ['Μέχρι την Πέμπτη', 'Μέχρι το Σάββατο', 'Μέχρι αύριο'], a: 0 }
  ] },
{ id: 'heatwave', stage: 4, title: 'Καύσωνας: οδηγίες για τις επόμενες μέρες', en: 'Heatwave: advice for the coming days', level: 'B2',
  text: `Νέο κύμα καύσωνα πλήττει τη χώρα από σήμερα, με θερμοκρασίες που αναμένεται να φτάσουν τους 42 βαθμούς στα ηπειρωτικά. Η Πολιτική Προστασία καλεί τους πολίτες να αποφεύγουν τις μετακινήσεις τις ώρες αιχμής, από τις 12 το μεσημέρι μέχρι τις 5 το απόγευμα, και να πίνουν άφθονο νερό. Ιδιαίτερη προσοχή συνιστάται για τους ηλικιωμένους και τα μικρά παιδιά. Οι δήμοι έχουν ανοίξει κλιματιζόμενες αίθουσες για όσους δεν διαθέτουν κλιματιστικό στο σπίτι. Παράλληλα, ο κίνδυνος πυρκαγιάς είναι πολύ υψηλός και απαγορεύεται κάθε είδους καύση σε δασικές περιοχές. Ο καιρός αναμένεται να βελτιωθεί από την Κυριακή.`,
  q: [
    { q: 'Ποιες ώρες πρέπει να αποφεύγουμε τις μετακινήσεις;', o: ['9:00–12:00', '12:00–17:00', '17:00–20:00'], a: 1 },
    { q: 'Τι έχουν κάνει οι δήμοι;', o: ['Έκλεισαν τα σχολεία', 'Άνοιξαν κλιματιζόμενες αίθουσες', 'Μοίρασαν νερό'], a: 1 },
    { q: 'Τι σημαίνει «απαγορεύεται»;', o: ['It is allowed', 'It is forbidden', 'It is advised'], a: 1 }
  ] },
{ id: 'insta', stage: 4, title: 'Μια ανάρτηση στο Instagram', en: 'An Instagram post', level: 'B2',
  text: `Τρία χρόνια πριν παράτησα τη δουλειά μου στο γραφείο και γύρισα στο νησί για να ανοίξω ένα μικρό φούρνο. Όλοι μου έλεγαν ότι είμαι τρελή. «Ποιος αφήνει σίγουρο μισθό για να ζυμώνει ψωμί;» Ε, εγώ. Οι πρώτοι μήνες ήταν δύσκολοι, δεν το κρύβω. Ξυπνούσα στις τέσσερις, έκανα λάθη, έκαιγα ψωμιά. Σιγά σιγά όμως έμαθα, και ο κόσμος άρχισε να έρχεται. Σήμερα ψήνουμε προζυμένιο ψωμί, κουλούρια και τις πίτες της γιαγιάς μου. Αν περάσετε από το λιμάνι, ελάτε για καφέ. Και αν σκέφτεστε να κάνετε κάτι τρελό… κάντε το. #φούρνος #νησί #ζωή`,
  q: [
    { q: 'Τι δουλειά έκανε πριν;', o: ['Ήταν φούρναρισσα', 'Δούλευε σε γραφείο', 'Ήταν σερβιτόρα'], a: 1 },
    { q: 'Τι σημαίνει «παράτησα»;', o: ['I gave up / quit', 'I found', 'I started'], a: 0 },
    { q: 'Ποια είναι η συμβουλή της;', o: ['Μην αφήνετε τη δουλειά σας', 'Αν σκέφτεστε κάτι τρελό, κάντε το', 'Ξυπνάτε νωρίς'], a: 1 }
  ] },
{ id: 'moving', stage: 4, title: 'Μετακόμιση στην Αθήνα', en: 'Moving to Athens', level: 'B2',
  text: `Όταν μετακόμισα στην Αθήνα, το πρώτο που με εντυπωσίασε ήταν ο θόρυβος. Μηχανάκια, κόρνες, γείτονες που μιλούν δυνατά στα μπαλκόνια μέχρι τα μεσάνυχτα. Στην αρχή δυσκολεύτηκα να κοιμηθώ. Μετά από λίγους μήνες όμως κατάλαβα ότι αυτός ο θόρυβος είναι η ζωή της πόλης. Οι γείτονες που με ενοχλούσαν έγιναν φίλοι μου· η κυρία Βούλα από απέναντι μου φέρνει φαγητό κάθε Κυριακή και ρωτάει πότε θα παντρευτώ. Η γραφειοκρατία είναι άλλο θέμα: για ένα απλό χαρτί χρειάστηκε να πάω τρεις φορές στην εφορία. Παρόλα αυτά, όταν βλέπω την Ακρόπολη φωτισμένη το βράδυ, ξεχνάω όλα τα προβλήματα.`,
  q: [
    { q: 'Τι τον ενόχλησε στην αρχή;', o: ['Η ζέστη', 'Ο θόρυβος', 'Το φαγητό'], a: 1 },
    { q: 'Τι κάνει η κυρία Βούλα;', o: ['Του φέρνει φαγητό', 'Παραπονιέται για τον θόρυβο', 'Του νοικιάζει το σπίτι'], a: 0 },
    { q: 'Πόσες φορές πήγε στην εφορία;', o: ['Μία', 'Δύο', 'Τρεις'], a: 2 }
  ] },
{ id: 'easter', stage: 3, title: 'Το ελληνικό Πάσχα', en: 'Greek Easter', level: 'B2',
  text: `Το Πάσχα είναι η μεγαλύτερη γιορτή της χρονιάς για τους Έλληνες. Τη Μεγάλη Εβδομάδα πολλοί νηστεύουν και πηγαίνουν στην εκκλησία. Τη Μεγάλη Πέμπτη βάφουν κόκκινα αυγά και φτιάχνουν τσουρέκια. Το βράδυ του Μεγάλου Σαββάτου όλοι κρατούν λαμπάδες και περιμένουν τα μεσάνυχτα. Όταν ο παπάς λέει «Χριστός Ανέστη», οι καμπάνες χτυπούν, ακούγονται βεγγαλικά και ο κόσμος φιλιέται. Μετά τρώνε μαγειρίτσα και τσουγκρίζουν αυγά. Την Κυριακή του Πάσχα ψήνεται αρνί στη σούβλα από νωρίς το πρωί, και η γιορτή με φαγητό, μουσική και χορό κρατάει μέχρι το βράδυ.`,
  q: [
    { q: 'Πότε βάφουν τα αυγά;', o: ['Τη Μεγάλη Πέμπτη', 'Την Κυριακή', 'Το Μεγάλο Σάββατο'], a: 0 },
    { q: 'Τι λέει ο παπάς τα μεσάνυχτα;', o: ['Χρόνια πολλά', 'Χριστός Ανέστη', 'Καλή Ανάσταση'], a: 1 },
    { q: 'Τι ψήνεται την Κυριακή;', o: ['Χοιρινό', 'Αρνί στη σούβλα', 'Ψάρι'], a: 1 }
  ] },
{ id: 'filotimo', stage: 4, title: 'Τι είναι το φιλότιμο;', en: 'What is filotimo?', level: 'C1',
  text: `Το φιλότιμο θεωρείται μια από τις πιο δύσκολα μεταφράσιμες ελληνικές λέξεις. Κυριολεκτικά σημαίνει «αγάπη για την τιμή», όμως στην πράξη περιγράφει κάτι πολύ ευρύτερο: την εσωτερική ανάγκη να κάνεις το σωστό, να φερθείς με αξιοπρέπεια και γενναιοδωρία, ακόμα και όταν κανείς δεν σε βλέπει. Ο άνθρωπος με φιλότιμο δεν βοηθάει επειδή περιμένει αντάλλαγμα, αλλά επειδή αλλιώς θα ντρεπόταν απέναντι στον εαυτό του. Όταν λέμε σε κάποιον «έλα, κάνε το για το φιλότιμο», δεν του ζητάμε απλώς μια χάρη· απευθυνόμαστε στην αίσθηση ευθύνης του. Κάποιοι υποστηρίζουν ότι η έννοια έχει υπερτιμηθεί, άλλοι ότι είναι η ουσία της ελληνικής κουλτούρας.`,
  q: [
    { q: 'Τι σημαίνει κυριολεκτικά «φιλότιμο»;', o: ['Αγάπη για τα λεφτά', 'Αγάπη για την τιμή', 'Φιλία'], a: 1 },
    { q: 'Γιατί βοηθάει ο άνθρωπος με φιλότιμο;', o: ['Για να πάρει κάτι πίσω', 'Γιατί αλλιώς θα ντρεπόταν', 'Γιατί τον υποχρεώνουν'], a: 1 },
    { q: 'Τι σημαίνει «αντάλλαγμα»;', o: ['Something in return', 'An apology', 'A gift'], a: 0 }
