    const PE = { AR: ['o', 'as', 'a', 'amos', 'áis', 'an'], ER: ['o', 'es', 'e', 'emos', 'éis', 'en'], IR: ['o', 'es', 'e', 'imos', 'ís', 'en'] }[g];
