      else if (/gu(ir)$/.test(inf)) T.present[0] = changeStem(stem, code).slice(0, -1) + 'o';
      if (/uir$/.test(inf) && !/guir$/.test(inf)) T.present = T.present.map((f, i) => i === 3 || i === 4 ? f : f.replace(/u(?=[oae])/, 'uy'));
    }
    // preterite
    if (irr.preterite) T.preterite = irr.preterite.slice();
    else if (irr.pret) {
