      const vowelStem = g !== 'AR' && /[aeo]$/.test(stem);
      if (vowelStem) E = ['í', 'íste', 'yó', 'ímos', 'ísteis', 'yeron'];
      if (/uir$/.test(inf) && !/guir$/.test(inf)) E = ['í', 'iste', 'yó', 'imos', 'isteis', 'yeron'];
