  }

  function splitArticle(input) {
    const t = (input || '').trim().replace(/\s+/g, ' ');
    const m = t.match(/^(el|la|los|las|un|una)\s+(.+)$/i);
    return m ? { article: lower(m[1]), word: m[2] } : { article: '', word: t };
  }
