      conditional: { what: 'Would', ex: ['I would speak', 'you would speak', 'he/she would speak', 'we would speak', 'you would speak', 'they would speak'] },
      perfect: { what: 'Has/have done (he + …)', ex: ['I have spoken', 'you have spoken', 'he/she has spoken', 'we have spoken', 'you have spoken', 'they have spoken'] },
