/* Family: create or join a family group, weekly league, family streak, team challenge, game scores and reactions.
   Talks to a small Supabase database only through its functions (create_family, join_family, family_sync, family_state,
   family_react, family_admin). Shared: nickname, avatar, language, daily XP / new words / games, game bests. Nothing else. */
(function () {
  const A = window.App, esc = A.esc;
  const URL_ = 'https://dcocnugizdcwkpoofeyr.supabase.co';
  const KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRjb2NudWdpemRjd2twb29mZXlyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTM1Njc3NzAsImV4cCI6MjEwOTE0Mzc3MH0.gUt0dUJoDFjirUc3fpmNzhoNGysykn1YEq7i5sYBJss';
  const AVATARS = ['🦉', '🐯', '🦊', '🐼', '🐨', '🐸', '🦄', '🐙', '🐬', '🦁', '🐻', '🐰', '🐵', '🐧', '🦖', '🐝', '🐱', '🐶'];
  const REACTS = ['👏', '🔥', '💪', '😂', '❤️', '🏆', '👀', '🎉'];
  const FLAG = { el: '🇬🇷', es: '🇪🇸', fr: '🇫🇷' };
  const DAY_CAP = 200; // XP counted per person per day in the league, so nobody wins just by grinding
  const PUZZLE = { el: 'Λεξούλα', es: 'Palabrita', fr: 'Motus' };

  A.family = A.global.family || null; // { token, member, nickname, avatar }
  const saveFam = () => { A.global.family = A.family; A.saveGlobal(); };
  let state = A.global.familyCache || null;

  async function rpc(fn, args) {
    let res;
    try {
      res = await fetch(`${URL_}/rest/v1/rpc/${fn}`, { method: 'POST', headers: { 'content-type': 'application/json', apikey: KEY, authorization: 'Bearer ' + KEY }, body: JSON.stringify(args || {}) });
    } catch (e) { throw new Error('No connection. Family features need the internet.'); }
    const txt = await res.text(); let data = null; try { data = txt ? JSON.parse(txt) : null; } catch (e) { /* ignore */ }
    if (!res.ok) {
      const msg = (data && (data.message || data.hint)) || 'Something went wrong (' + res.status + ')';
      if (/NOT_MEMBER/.test(msg)) { A.family = null; state = null; A.global.familyCache = null; saveFam(); throw new Error('You are no longer in this family.'); }
      throw new Error(msg);
    }
    return data;
  }

  // ---------- my progress, across all languages on this phone ----------
  function allDbs() {
    const out = [];
    const cur = A.LANG.code === 'el' ? 'lexeis.v1' : 'lexeis.v1.' + A.LANG.code;
    ['lexeis.v1', 'lexeis.v1.es', 'lexeis.v1.fr'].forEach(k => {
      if (A.db && cur === k) return out.push(A.db);
      try { const d = JSON.parse(localStorage.getItem(k)); if (d) out.push(d); } catch (e) { /* ignore */ }
    });
    if (A.db && !out.includes(A.db)) out.push(A.db);
    return out;
  }
  function myDays() {
    const days = {}, dbs = allDbs();
    for (let i = 0; i < 14; i++) {
      const k = A.dayKey(A.today() - i * 864e5); let xp = 0, words = 0, games = 0;
      dbs.forEach(d => { const x = d.stats && d.stats.days && d.stats.days[k]; if (x) { xp += x.xp || 0; words += x.new || 0; games += x.games || 0; } });
      if (xp || words || games) days[k] = { xp, words, games };
    }
    return days;
  }
  function myScores() {
    const out = {};
    allDbs().forEach(d => { const g = d.games; if (!g) return; Object.entries(g.best || {}).forEach(([k, v]) => { out[k] = Math.max(out[k] || 0, v); }); });
    return out;
  }
  function myStats() {
    let words = 0; allDbs().forEach(d => { words += (d.words || []).length; });
    return { streak: A.streak ? A.streak() : 0, words, level: A.levelInfo ? A.levelInfo().level : 1 };
  }
  let pushTimer = null;
  A.familyPush = function (now) {
    if (!A.family) return Promise.resolve();
    clearTimeout(pushTimer);
    const go = () => rpc('family_sync', { p_token: A.family.token, p_nickname: A.family.nickname, p_avatar: A.family.avatar, p_lang: A.LANG.code, p_stats: myStats(), p_days: myDays(), p_scores: myScores() }).catch(() => {});
    if (now) return go();
    return new Promise(r => { pushTimer = setTimeout(() => go().then(r), 4000); });
  };
  const _xp = A.xp;
  A.xp = function (n) { _xp(n); if (A.family) A.familyPush(); };

  async function refresh() {
    if (!A.family) return null;
    await A.familyPush(true);
    state = await rpc('family_state', { p_token: A.family.token });
    A.global.familyCache = state; A.saveGlobal();
    return state;
  }

  // ---------- numbers from the shared state ----------
  const weekStart = () => { const d = new Date(A.today()); const dow = (d.getDay() + 6) % 7; return A.dayKey(A.today() - dow * 864e5); };
  function calc(st) {
    const ws = weekStart(), today = A.dayKey(), act = st.activity || [];
    const by = {}; st.members.forEach(m => { by[m.id] = { m, week: 0, today: 0, words: 0, games: 0, days: new Set() }; });
    act.forEach(a => { const b = by[a.m]; if (!b) return; if (a.xp > 0) b.days.add(a.d); if (a.d >= ws) { b.week += Math.min(a.xp, DAY_CAP); b.words += a.w; b.games += a.g; } if (a.d === today) b.today = a.xp; });
    const league = Object.values(by).sort((x, y) => y.week - x.week);
    // family streak: days on which every member (who had joined by then) practised
    let fs = 0, t = A.today();
    const allOn = k => st.members.every(m => A.dayKey(new Date(m.joined).getTime()) > k || by[m.id].days.has(k));
    if (!allOn(A.dayKey(t))) t -= 864e5;
    for (let i = 0; i < 60 && allOn(A.dayKey(t)); i++) { fs++; t -= 864e5; }
    const waiting = st.members.filter(m => !by[m.id].days.has(today));
    // team challenge
    let ch = st.family.challenge, prog = 0;
    if (ch && ch.target) { const from = ch.start || ws; act.forEach(a => { if (a.d >= from && by[a.m]) prog += ch.type === 'words' ? a.w : ch.type === 'games' ? a.g : Math.min(a.xp, DAY_CAP); }); }
    return { by, league, fs, waiting, ch, prog };
  }

  // small card for Today and Games
  A.familyCard = function () {
    if (!A.family) return `<a class="fam-card invite" href="#/family"><span class="fc-ico">👨‍👩‍👧‍👦</span><span class="fc-text"><strong>Family</strong><small>Make a family group and compete in a weekly league.</small></span></a>`;
    if (!state) return `<a class="fam-card" href="#/family"><span class="fc-ico">👨‍👩‍👧‍👦</span><span class="fc-text"><strong>Family</strong><small>Loading…</small></span></a>`;
    const c = calc(state), me = c.league.findIndex(x => x.m.id === state.me) + 1;
    const wait = c.waiting.filter(m => m.id !== state.me).map(m => m.avatar).join('');
    return `<a class="fam-card" href="#/family"><span class="fc-flame">🔥<b>${c.fs}</b></span><span class="fc-text"><strong>${esc(state.family.name)}</strong><small>${me ? `You're ${ordinal(me)} this week` : ''}${c.waiting.length ? ` · waiting for ${wait || 'you'}` : ' · everyone practised today 🎉'}</small></span><span class="fc-avs">${c.league.slice(0, 4).map(x => `<span>${x.m.avatar}</span>`).join('')}</span></a>`;
  };
  const ordinal = n => n + (['th', 'st', 'nd', 'rd'][(n % 100 - 20) % 10] || ['th', 'st', 'nd', 'rd'][n % 100] || 'th');

  // ---------- screens ----------
  let form = { mode: null, avatar: AVATARS[Math.floor(Math.random() * AVATARS.length)] };
  A.routes.family = function () {
    if (!A.family) return renderJoin();
    renderFamily();
    refresh().then(() => { if ((location.hash || '').startsWith('#/family')) renderFamily(); }).catch(e => { const n = A.$('#famNote'); if (n) n.textContent = e.message; if (!A.family) renderJoin(); });
  };
  function avatarPicker() { return `<div class="av-pick">${AVATARS.map(a => `<button type="button" class="${a === form.avatar ? 'on' : ''}" data-act="fam-av" data-a="${a}">${a}</button>`).join('')}</div>`; }
  function renderJoin() {
    const m = form.mode;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/today">Today</a><h1>Family 👨‍👩‍👧‍👦</h1><p class="muted">Learn together: a weekly league, a family streak that only grows when everyone practises, team challenges and game scores. Each person learns their own language at their own level.</p></header>
      ${!m ? `<button class="btn primary wide big" data-act="fam-mode" data-m="create">Create a family</button><button class="btn wide big" data-act="fam-mode" data-m="join">Join with a code</button>
        <p class="tiny">Only what's needed is shared with your family: nickname, avatar, language, how much you practised each day and game scores. Your words and chats stay on this phone. There's no messaging, just emoji reactions.</p>` : `
      <form data-form="fam" class="word-form" autocomplete="off">
        ${m === 'join' ? '<label class="field"><span>Family code</span><input name="code" placeholder="e.g. K7M2QP" autocapitalize="characters" required maxlength="8" style="text-transform:uppercase;letter-spacing:3px;font-weight:700"></label>' : '<label class="field"><span>Family name</span><input name="fname" placeholder="e.g. The Onefti family" maxlength="40"></label>'}
        <label class="field"><span>Your nickname</span><input name="nick" required maxlength="24" placeholder="e.g. Dad, Leo, Mia"></label>
        <p class="label">Your avatar</p>${avatarPicker()}
        <button class="btn primary wide big" type="submit">${m === 'join' ? 'Join family' : 'Create family'}</button>
        <button type="button" class="btn ghost wide" data-act="fam-mode" data-m="">Back</button>
        ${m === 'create' ? '<p class="tiny">You\'ll be the family head: you can rename the family, set team challenges, and add or remove people.</p>' : ''}
        <p class="hint warn" id="famErr" hidden></p></form>`}`;
  }
  A.acts['fam-mode'] = el => { form.mode = el.dataset.m || null; renderJoin(); };
  A.acts['fam-av'] = el => { form.avatar = el.dataset.a; A.$$('.av-pick button').forEach(b => b.classList.toggle('on', b === el)); };
  A.forms.fam = async function (f, fd) {
    const err = A.$('#famErr'), btn = A.$('button[type=submit]', f); err.hidden = true; btn.disabled = true;
    const nick = (fd.get('nick') || '').trim();
    try {
      const r = form.mode === 'join'
        ? await rpc('join_family', { p_code: (fd.get('code') || '').trim(), p_nickname: nick, p_avatar: form.avatar, p_lang: A.LANG.code })
        : await rpc('create_family', { p_name: (fd.get('fname') || '').trim(), p_nickname: nick, p_avatar: form.avatar, p_lang: A.LANG.code });
      A.family = { token: r.token, member: r.member_id, nickname: nick, avatar: form.avatar }; saveFam();
      A.toast(form.mode === 'join' ? 'Welcome to the family!' : 'Family ready!'); form.mode = null;
      if (A.confetti) A.confetti();
      A.routes.family();
    } catch (e) { err.textContent = e.message; err.hidden = false; btn.disabled = false; }
  };

  let tab = 'league';
  function renderFamily() {
    if (!state) { A.view().innerHTML = `<header class="top"><a class="back" href="#/today">Today</a><h1>Family</h1></header><section class="done-card"><div class="spinner"></div><p class="muted" id="famNote">Loading your family…</p></section>`; return; }
    const st = state, c = calc(st), meM = st.members.find(m => m.id === st.me) || {}, head = meM.role === 'head';
    const tabs = [['league', 'League'], ['games', 'Games'], ['family', 'Family']].concat(head ? [['head', '⭐ Head']] : []);
    let body = '';
    if (tab === 'league') {
      const max = Math.max(1, ...c.league.map(x => x.week));
      body = `<section class="fam-hero"><div class="fh-flame ${c.fs ? '' : 'out'}">🔥</div><div><p class="fh-num">${c.fs} day${c.fs === 1 ? '' : 's'}</p><p class="tiny">Family streak: grows on days when everyone practises.</p>
          <p class="fh-wait">${c.waiting.length ? 'Still to practise today: ' + c.waiting.map(m => `${m.avatar} ${esc(m.nickname)}`).join(', ') : '✅ Everyone has practised today!'}</p></div></section>
        ${c.ch && c.ch.target ? `<section class="fam-ch"><p class="label">Team challenge</p><p><b>${esc(c.ch.title || 'Team challenge')}</b></p><div class="xp-bar big"><i style="width:${Math.min(100, c.prog / c.ch.target * 100)}%"></i></div><p class="tiny">${c.prog} / ${c.ch.target} ${{ xp: 'XP', words: 'new words', games: 'games' }[c.ch.type] || ''}${c.prog >= c.ch.target ? ' · 🎉 Done! Well played, team.' : ''}</p></section>` : head ? `<button class="btn wide" data-act="fam-tab" data-t="head">⭐ Set a team challenge</button>` : ''}
        <h2>This week</h2><p class="tiny">XP since Monday. Up to ${DAY_CAP} XP a day counts, so steady practice beats one long session.</p>
        <ol class="league">${c.league.map((x, i) => `<li class="${x.m.id === st.me ? 'me' : ''}"><span class="lg-pos">${['🥇', '🥈', '🥉'][i] || i + 1}</span><span class="lg-av">${x.m.avatar}</span><span class="lg-main"><b>${esc(x.m.nickname)}</b> <span class="tiny">${FLAG[x.m.lang] || ''}${x.today ? ' · ✓ today' : ''}${x.m.stats && x.m.stats.streak ? ' · 🔥' + x.m.stats.streak : ''}</span><span class="lg-bar"><i style="width:${x.week / max * 100}%"></i></span></span><span class="lg-xp">${x.week}</span></li>`).join('')}</ol>`;
