        <section class="fam-invite"><p class="label">Invite someone</p><p class="fam-code">${esc(st.family.code)}</p><p class="tiny">They open Λέξεις → Family → Join with a code.</p><button class="btn sm" data-act="fam-share">Share the code</button></section>
