    } else if (tab === 'head') {
      const ch = c.ch || {};
      body = `<section><h2>Team challenge</h2><p class="tiny">Set a goal for everyone to reach together this week. Progress shows for the whole family.</p>
          <div class="chips wrap">${[['xp', 1000, 'Earn 1,000 XP together'], ['xp', 2500, 'Earn 2,500 XP together'], ['words', 30, 'Learn 30 new words together'], ['words', 75, 'Learn 75 new words together'], ['games', 20, 'Play 20 games together']].map(([t, n, title]) => `<button class="chip ${ch.type === t && ch.target === n ? 'on' : ''}" data-act="fam-ch" data-t="${t}" data-n="${n}" data-title="${esc(title)}">${esc(title)}</button>`).join('')}</div>
          ${ch.target ? '<button class="btn sm ghost" data-act="fam-ch" data-t="">Clear the challenge</button>' : ''}</section>
