        <section><h2>Family code</h2><p class="fam-code">${esc(st.family.code)}</p><p class="tiny">Make a new code if the old one was shared too widely. People already in the family stay in.</p><button class="btn sm" data-act="fam-admin" data-a="new_code">New code</button></section>
        <section><h2>People</h2><ul class="fam-members">${st.members.filter(m => m.id !== st.me).map(m => `<li><span class="fm-av">${m.avatar}</span><span class="fm-main"><b>${esc(m.nickname)}</b></span><button class="btn sm" data-act="fam-admin" data-a="make_head" data-m="${m.id}" data-confirm="Make ${esc(m.nickname)} the family head? You'll become a normal member.">Make head</button><button class="btn sm danger" data-act="fam-admin" data-a="remove" data-m="${m.id}" data-confirm="Remove ${esc(m.nickname)} from the family?">Remove</button></li>`).join('') || '<li class="tiny">Nobody else yet. Share the code!</li>'}</ul></section>`;
    }
    A.view().innerHTML = `<header class="top"><a class="back" href="#/today">Today</a><h1>${esc(st.family.name)}</h1><p class="muted" id="famNote">${st.members.length} ${st.members.length === 1 ? 'person' : 'people'} · code <b>${esc(st.family.code)}</b></p></header>
      <div class="seg fam-tabs">${tabs.map(([k, l]) => `<button class="${tab === k ? 'on' : ''}" data-act="fam-tab" data-t="${k}">${l}</button>`).join('')}</div>${body}`;
  }
  const ago = t => { const s = (Date.now() - new Date(t).getTime()) / 1000; return s < 90 ? 'just now' : s < 5400 ? Math.round(s / 60) + ' min ago' : s < 129600 ? Math.round(s / 3600) + ' h ago' : Math.round(s / 86400) + ' days ago'; };
  A.acts['fam-tab'] = el => { tab = el.dataset.t; renderFamily(); };
