    catch (e) { A.toast(e.message); }
  };
  A.acts['fam-ch'] = async function (el) {
    const v = el.dataset.t ? { type: el.dataset.t, target: +el.dataset.n, title: el.dataset.title, start: weekStart() } : null;
    try { await rpc('family_admin', { p_token: A.family.token, p_action: 'challenge', p_member: null, p_value: v }); await refresh(); tab = 'league'; renderFamily(); A.toast(v ? 'Challenge set' : 'Challenge cleared'); }
    catch (e) { A.toast(e.message); }
  };
  A.forms['fam-rename'] = async function (f, fd) {
    try { await rpc('family_admin', { p_token: A.family.token, p_action: 'rename', p_member: null, p_value: (fd.get('n') || '').trim() }); await refresh(); renderFamily(); A.toast('Saved'); }
    catch (e) { A.toast(e.message); }
  };
  A.acts['fam-myav'] = async function (el) { A.family.avatar = el.dataset.a; saveFam(); await A.familyPush(true); await refresh().catch(() => {}); renderFamily(); };
  A.acts['fam-share'] = function () {
    const txt = `Join our family on Λέξεις! Open the app → Family → Join with a code, and type: ${state.family.code}`;
    if (navigator.share) navigator.share({ text: txt }).catch(() => {}); else { try { navigator.clipboard.writeText(txt); A.toast('Copied'); } catch (e) { A.toast(state.family.code); } }
  };
  A.acts['fam-leave'] = async function () {
    if (!window.confirm('Leave this family? Your progress on this phone stays.')) return;
    try { await rpc('family_admin', { p_token: A.family.token, p_action: 'leave', p_member: null, p_value: null }); A.family = null; state = null; A.global.familyCache = null; saveFam(); A.toast('You left the family'); A.go('#/today'); }
    catch (e) { A.toast(e.message); }
  };

  // ---------- Today screen card, cheers toast ----------
  const _today = A.routes.today;
  A.routes.today = function () {
    _today.apply(this, arguments);
    const anchor = A.$('.daily-card') || A.$('.stage-card');
    const wrap = document.createElement('div'); wrap.id = 'famSlot'; wrap.innerHTML = A.familyCard();
    if (anchor) anchor.parentNode.insertBefore(wrap, anchor); else A.view().appendChild(wrap);
