      A.toast(mine.length === 1 ? `${nm(mine[0].from)} sent you ${mine[0].emoji}` : `${mine.length} cheers from your family: ${mine.map(r => r.emoji).join('')}`);
      A.global.famSeen = mine[0].at; A.saveGlobal();
