  }
  // the app's first screen was drawn before games and family loaded: draw it again if it's one of ours
  if (['today', 'games', 'rain', 'pairs', 'wordle', 'family'].includes(document.body.dataset.route)) A.render();
  // sync when the app comes back to the front
  document.addEventListener('visibilitychange', () => { if (!document.hidden && A.family) A.familyPush(true); });
