/* Games: Word Rain, Memory pairs, Daily word puzzle. Work in every language pack; scores feed XP and the family league. */
(function () {
  const A = window.App, G = window.Greek || window.Spanish || window.French, esc = A.esc;
  const LG = () => A.LANG.code;

  function gstore() { A.db.games = A.db.games || { best: {}, word: {}, played: 0 }; return A.db.games; }
  function finish(game, score, xp) {
    const s = gstore(); s.played++;
    const prev = s.best[game] || 0, isBest = score > prev;
    if (isBest) s.best[game] = score;
    A.bumpDay('games'); if (xp) A.xp(xp);
    A.save();
    if (A.familyPush) A.familyPush();
    return { prev, isBest };
  }
  const short = m => String(m || '').split(/[;,(]/)[0].trim();
  // words to play with: your own first, topped up from the dictionary at your level
  function wordPool(n) {
    const mine = A.db.words.filter(w => w.meaning && w.lemma && !/\s/.test(w.lemma)).map(w => ({ head: A.plainHead(w), lemma: w.lemma, meaning: short(w.meaning), emoji: w.emoji || '' }));
    const dict = A.stageDict().filter(e => e.meaning && !/\s/.test(e.lemma)).map(e => ({ head: A.entryHead(e), lemma: e.lemma, meaning: short(e.meaning), emoji: e.emoji || '' }));
    const seen = new Set(), out = [];
    A.shuffle(mine).concat(A.shuffle(dict)).forEach(x => { if (!seen.has(x.meaning) && !seen.has(x.lemma) && out.length < n) { seen.add(x.meaning); seen.add(x.lemma); out.push(x); } });
    return out;
  }

  // ---------------- HUB ----------------
  A.routes.games = function () {
    const s = gstore(), today = (s.word[A.dayKey()] || null);
    A.view().innerHTML = `<header class="top"><a class="back" href="#/practice">Practice</a><h1>Games</h1><p class="muted">Play with your words. Every game earns XP${A.family && A.family.token ? ' and counts for your family' : ''}.</p></header>
      <a class="game-card gc-rain" href="#/rain"><span class="gc-ico">🌧️</span><span class="gc-text"><strong>Word Rain</strong><small>Words fall. Tap the meaning before they land.</small></span><span class="gc-best">${s.best.rain ? '🏆 ' + s.best.rain : 'New'}</span></a>
      <a class="game-card gc-pairs" href="#/pairs"><span class="gc-ico">🃏</span><span class="gc-text"><strong>Memory pairs</strong><small>Flip the cards and match each word with its meaning.</small></span><span class="gc-best">${s.best.pairs ? '🏆 ' + s.best.pairs : 'New'}</span></a>
      <a class="game-card gc-word" href="#/wordle"><span class="gc-ico">🔤</span><span class="gc-text"><strong>${esc(PUZZLE_NAME[LG()] || 'Word of the day')}</strong><small>Guess today's 5-letter word in 6 tries. Same puzzle for everyone.</small></span><span class="gc-best">${today ? (today.won ? '✓ ' + today.tries + '/6' : '✗') : 'Today'}</span></a>
      <a class="game-card gc-sprint" href="#/articles"><span class="gc-ico">⚡</span><span class="gc-text"><strong>Article sprint</strong><small>60 seconds of gender: how many can you get?</small></span><span class="gc-best"></span></a>
      ${A.familyCard ? A.familyCard() : ''}`;
  };

  // ---------------- WORD RAIN ----------------
  let rain = null;
  A.routes.rain = function () {
    stopRain();
    const best = gstore().best.rain || 0;
    A.view().innerHTML = `<header class="top"><a class="back" href="#/games">Games</a><h1>Word Rain 🌧️</h1><p class="muted">${esc(A.LANG.name)} words fall from the sky. Tap the right meaning before each one lands. 3 lives. It gets faster!</p></header>
      <section class="done-card">${best ? `<p class="big-num">${best}</p><p class="muted">Your best</p>` : '<p class="big-num">🌧️</p>'}
      <button class="btn primary wide big" data-act="rain-go">Play</button></section>`;
  };
  function stopRain() { if (rain) { cancelAnimationFrame(rain.raf); rain.over = true; rain = null; } }
  A.acts['rain-go'] = function () {
    const pool = wordPool(80);
    if (pool.length < 6) return A.toast('Add a few words first');
    A.view().innerHTML = `<div class="rain-wrap"><div class="rain-top"><a class="back" href="#/games" data-act="rain-stop">Stop</a><span class="rain-lives" id="rlives">❤️❤️❤️</span><span class="rain-score" id="rscore">0</span></div>
      <div class="rain-sky" id="sky"><div class="rain-ground"></div></div>
      <div class="rain-opts" id="ropts"></div></div>`;
    rain = { pool, drops: [], score: 0, lives: 3, combo: 0, speed: 60, last: performance.now(), spawnIn: 0, n: 0, over: false };
    rain.raf = requestAnimationFrame(tick);
  };
  A.acts['rain-stop'] = () => stopRain();
  function spawn() {
    const used = new Set(rain.drops.map(d => d.w.lemma));
    const w = A.pick(rain.pool.filter(x => !used.has(x.lemma)));
    const sky = A.$('#sky'); if (!sky) return;
    const el = document.createElement('div'); el.className = 'drop'; el.lang = LG();
    el.innerHTML = `${w.emoji && A.LANG.audience === 'kid' ? `<span>${w.emoji}</span> ` : ''}${esc(w.head)}`;
    el.style.left = (8 + Math.random() * 52) + '%';
    sky.appendChild(el);
    rain.drops.push({ w, el, y: -40 });
    rain.n++;
    if (rain.drops.length === 1) options();
  }
  function options() {
    const box = A.$('#ropts'); if (!box) return;
    const d = rain.drops[0]; if (!d) { box.innerHTML = ''; return; }
    const others = A.shuffle(rain.pool.filter(x => x.meaning !== d.w.meaning)).slice(0, 3).map(x => x.meaning);
    const o = A.shuffle(others.concat(d.w.meaning));
    box.innerHTML = o.map(m => `<button class="opt" data-act="rain-pick" data-m="${esc(m)}">${esc(m)}</button>`).join('');
    d.el.classList.add('target');
  }
  function tick(now) {
    if (!rain || rain.over) return;
    if (!A.$('#sky')) { stopRain(); return; }
    const dt = Math.min(0.05, (now - rain.last) / 1000); rain.last = now;
    const H = A.$('#sky').clientHeight - 46;
    rain.spawnIn -= dt;
    const maxDrops = rain.score >= 150 ? 3 : rain.score >= 60 ? 2 : 1;
    if (rain.spawnIn <= 0 && rain.drops.length < maxDrops) { spawn(); rain.spawnIn = Math.max(1.2, 3.2 - rain.n * 0.06); }
    rain.drops.forEach(d => { d.y += rain.speed * dt; d.el.style.transform = `translateY(${d.y}px)`; });
    const landed = rain.drops.find(d => d.y >= H);
    if (landed) { miss(landed); if (!rain) return; }
    rain.raf = requestAnimationFrame(tick);
  }
  function pop(d, ok) {
    d.el.classList.add(ok ? 'pop' : 'splash');
    setTimeout(() => d.el.remove(), 350);
    rain.drops = rain.drops.filter(x => x !== d);
  }
  function miss(d) {
    pop(d, false); rain.lives--; rain.combo = 0;
    A.$('#rlives').textContent = '❤️'.repeat(Math.max(0, rain.lives)) + '🖤'.repeat(3 - Math.max(0, rain.lives));
    A.sfx.wrong();
    const box = A.$('#ropts'); if (box) box.insertAdjacentHTML('afterbegin', `<p class="rain-miss" lang="${LG()}">${esc(d.w.head)} = ${esc(d.w.meaning)}</p>`);
    if (rain.lives <= 0) return endRain();
    setTimeout(() => { if (rain) options(); }, 700);
  }
  A.acts['rain-pick'] = function (el) {
    if (!rain || !rain.drops[0]) return;
    const d = rain.drops[0];
    if (el.dataset.m === d.w.meaning) {
      rain.combo++; const pts = 10 + Math.min(rain.combo - 1, 10) * 2;
      rain.score += pts; rain.speed = Math.min(150, 60 + rain.score / 5);
      A.$('#rscore').textContent = rain.score;
      A.sfx.right(); pop(d, true); options();
      if (rain.combo >= 3) { const c = document.createElement('div'); c.className = 'combo'; c.textContent = '×' + rain.combo; A.$('#sky').appendChild(c); setTimeout(() => c.remove(), 700); }
    } else { el.classList.add('wrong'); el.disabled = true; miss(d); }
  };
  function endRain() {
    const sc = rain.score; stopRain();
    const r = finish('rain', sc, Math.min(30, Math.round(sc / 10)));
    A.view().innerHTML = `<header class="top"><a class="back" href="#/games">Games</a><h1>Game over</h1></header>
      <section class="done-card"><p class="big-num">${sc}</p><p class="muted">${r.isBest && sc ? '🏆 New best!' : r.prev ? 'Best: ' + r.prev : ''}</p>
      <div class="row-btns"><button class="btn primary" data-act="rain-go">Play again</button><a class="btn" href="#/games">Games</a></div></section>`;
    if (r.isBest && sc && A.confetti) A.confetti();
  }

  // ---------------- MEMORY PAIRS ----------------
  let pairs = null;
  A.routes.pairs = function () {
    if (pairs && pairs.timer) clearInterval(pairs.timer);
    const best = gstore().best.pairs || 0, kid = A.LANG.audience === 'kid';
    A.view().innerHTML = `<header class="top"><a class="back" href="#/games">Games</a><h1>Memory pairs 🃏</h1><p class="muted">Flip two cards at a time. Match each ${esc(A.LANG.name)} word with its ${kid ? 'picture or ' : ''}meaning. Fewer flips and less time means more points.</p></header>
      <section class="done-card">${best ? `<p class="big-num">${best}</p><p class="muted">Your best</p>` : '<p class="big-num">🃏</p>'}
      <div class="row-btns"><button class="btn primary" data-act="pairs-go" data-n="6">6 pairs</button><button class="btn" data-act="pairs-go" data-n="8">8 pairs</button></div></section>`;
  };
  A.acts['pairs-go'] = function (el) {
    const n = +el.dataset.n || 6;
    const ws = wordPool(n); if (ws.length < n) return A.toast('Add a few words first');
    const kid = A.LANG.audience === 'kid';
    const cards = A.shuffle([].concat(...ws.map((w, i) => [{ i, side: 'w', text: w.head, lang: LG() }, { i, side: 'm', text: kid && w.emoji ? w.emoji : w.meaning, big: kid && !!w.emoji }])));
    pairs = { n, ws, cards, open: [], matched: new Set(), moves: 0, t0: Date.now(), lock: false };
    pairs.timer = setInterval(() => { const t = A.$('#ptime'); if (!t) return clearInterval(pairs.timer); t.textContent = Math.floor((Date.now() - pairs.t0) / 1000) + 's'; }, 500);
    renderPairs();
  };
  function renderPairs() {
    const p = pairs;
    A.view().innerHTML = `<div class="review"><div class="rv-top"><a class="back" href="#/pairs">Stop</a><span class="rv-count"><span id="pmoves">${p.moves}</span> flips · <span id="ptime">0s</span></span></div>
      <div class="pairs-grid n${p.n}">${p.cards.map((c, k) => `<button class="pcard ${p.matched.has(c.i) ? 'done' : ''} ${p.open.includes(k) ? 'open' : ''}" data-act="pairs-flip" data-k="${k}"><span class="pc-back">?</span><span class="pc-face ${c.big ? 'big' : ''}" ${c.lang ? `lang="${c.lang}"` : ''}>${esc(c.text)}</span></button>`).join('')}</div></div>`;
  }
  A.acts['pairs-flip'] = function (el) {
    const p = pairs, k = +el.dataset.k, c = p.cards[k];
    if (!p || p.lock || p.open.includes(k) || p.matched.has(c.i)) return;
    p.open.push(k); el.classList.add('open');
    if (c.side === 'w') A.speak && A.speak(p.ws[c.i].lemma);
    if (p.open.length < 2) return;
    p.moves++; A.$('#pmoves').textContent = p.moves;
    const [a, b] = p.open.map(x => p.cards[x]);
    if (a.i === b.i && a.side !== b.side) {
      p.matched.add(a.i); p.open = []; A.sfx.right();
      A.$$('.pcard.open').forEach(x => { x.classList.remove('open'); x.classList.add('done'); });
      if (p.matched.size === p.n) setTimeout(endPairs, 450);
    } else {
      p.lock = true;
      setTimeout(() => { A.$$('.pcard.open').forEach(x => x.classList.remove('open')); p.open = []; p.lock = false; }, 900);
    }
  };
  function endPairs() {
    const p = pairs; clearInterval(p.timer);
    const secs = Math.round((Date.now() - p.t0) / 1000), perfect = p.n;
    const score = Math.max(50, Math.round(p.n * 100 - (p.moves - perfect) * 15 - secs * 2));
    const r = finish('pairs', score, Math.min(25, 5 + p.n * 2));
    A.view().innerHTML = `<header class="top"><a class="back" href="#/games">Games</a><h1>All matched!</h1></header>
      <section class="done-card"><p class="big-num">${score}</p><p class="muted">${p.moves} flips · ${secs}s${r.isBest ? ' · 🏆 New best!' : r.prev ? ' · Best: ' + r.prev : ''}</p>
