/* Over-the-air updates: downloads the newest app files (JS + CSS) from the public updates repo and keeps them
   on the phone; loader.js uses them on the next start. Changes to the native shell still need a new APK. */
(function () {
  'use strict';
  const A = window.App;
  const BASE = 'https://raw.githubusercontent.com/jonefti/lexeis-updates/main/';
  const running = window.APP_BUILD || 0;
  const builtin = window.LEXEIS_BUILTIN_BUILD || 0;
  let busy = false;

  function status(msg, ok) {
    try { localStorage.setItem('lexeis.updStatus', JSON.stringify({ at: Date.now(), msg, ok: !!ok })); } catch (e) { /* ignore */ }
    const el = document.getElementById('updStatus'); if (el) el.textContent = A.updateStatus();
  }
  A.updateStatus = () => { try { const s = JSON.parse(localStorage.getItem('lexeis.updStatus')); return s ? new Date(s.at).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) + ': ' + s.msg : 'Not checked yet'; } catch (e) { return 'Not checked yet'; } };
  function offerApk(j, why) {
    A.sheet(`<h2>New version available</h2><p class="muted">${A.esc(why)}</p><p class="muted">Download the latest version and install it over this one; your words are kept.</p><div class="row-btns"><button class="btn primary" data-act="open-url" data-url="${A.esc((j && j.apk) || A.APK_URL)}">Download the latest version</button><button class="btn ghost" data-act="sheet-close">Later</button></div>`);
  }
  async function check(manual) {
    if (busy) return; busy = true;
    let j = null, step = 'reading the update feed';
    try {
      const res = await fetch(BASE + 'latest.json?t=' + Date.now(), { cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      j = await res.json();
      if (!(j.build > running)) { status(`Up to date (build ${running})`, true); if (manual) A.toast('You have the latest version'); return; }
      if (j.minNative && builtin && builtin < j.minNative) { status(`Build ${j.build} needs a new APK`); offerApk(j, 'This update changes the app itself, so it needs a quick reinstall.'); return; }
      if (!j.ota) throw new Error('no over-the-air bundle for build ' + j.build);
      step = 'downloading build ' + j.build;
      if (manual) A.toast('Downloading update…');
      const r2 = await fetch(BASE + j.ota + '?t=' + Date.now(), { cache: 'no-store' });
      if (!r2.ok) throw new Error('HTTP ' + r2.status);
      const bundle = await r2.json();
      if (!bundle || !bundle.files || !bundle.files['app.js']) throw new Error('bundle incomplete');
      step = 'saving build ' + j.build;
      localStorage.setItem('lexeis.ota', JSON.stringify(bundle));
      localStorage.removeItem('lexeis.otaBooting');
      status(`Build ${j.build} downloaded, ready to install`, true);
      A.sheet(`<h2>Update ready ✨</h2><p class="muted">${A.esc(j.notes || 'A new version of the app is ready.')}</p><div class="row-btns"><button class="btn primary" data-act="upd-now">Restart now</button><button class="btn ghost" data-act="upd-later">Next time</button></div>`);
    } catch (e) {
      const msg = `Failed while ${step}: ${(e && e.message) || String(e)}`;
      status(msg);
      if (manual) { if (j && j.build > running) offerApk(j, msg); else A.toast(msg); }
    } finally { busy = false; }
  }
  A.acts['upd-now'] = () => { A.save(); location.hash = '#/today'; location.reload(); };
  A.acts['upd-later'] = () => { A.closeSheet(); A.toast('It will update next time you open the app'); };
  A.checkUpdates = () => check(true);

  if (localStorage.getItem('lexeis.otaBad')) { status('An update failed to start, so the previous version was restored'); localStorage.removeItem('lexeis.otaBad'); }
  setTimeout(() => check(false), 4000);
})();
